comms.text:
@1 וִיהֵי חֳלַף דִי תְקַבְּלוּן יָת דִינַיָא הָאִלֵין וְתִטְרוּן וְתַעְבְּדוּן יָתְהוֹן וְיִטַר יְיָ אֱלָהָךְ לָךְ יָת קְיָמָא וְיָת חִסְדָא דִי קַיִים לַאֲבָהָתָךְ:
@2 וְיִרְחֲמִנָךְ וִיבָרֵכִנָךְ וְיַסְגִינָךְ וִיבָרֵךְ וַלְדָא דִמְעָךְ וְאִבָּא דְאַרְעָךְ עִבוּרָךְ וְחַמְרָךְ וּמִשְׁחָךְ בַּקְרֵי תוֹרָיךְ וְעֶדְרֵי עָנָךְ עַל אַרְעָא דִי קַיִים לַאֲבָהָתָךְ לְמִתַּן לָךְ:
@3 בְּרִיךְ תְּהֵי מִכָּל עַמְמַיָא לָא יְהֵי בָךְ עֲקַר וְעַקְרָא וּבִבְעִירָךְ:
@4 וְיֶעְדֵי יְיָ מִנָךְ כָּל מַרְעִין וְכָל מַכְתְּשֵׁי מִצְרַיִם בִּישַׁיָא דִי יְדַעַתְּ לָא יְשַׁוִּנוּן בָּךְ וְיִתְּנִנוּן בְּכָל סָנְאָךְ:
@5 וּתְגַמַר יָת כָּל עַמְמַיָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לָא תְחוּס עֵינָךְ עֲלֵיהוֹן וְלָא תִפְלַח יָת טַּעֲוָתְהוֹן אֲרֵי לְתַקְלָא הוּא לָךְ:
@6 דִילְמָא תֵימַר בְּלִבָּךְ סַגִיאִין עַמְמַיָא הָאִלֵין מִנִי אֶכְדֵין אִכּוּל לְתָרָכוּתְהוֹן:
@7 לָא תִדְחַל מִנְהוֹן מִדְכַּר תִּדְכַּר יָת דִי עֲבַד יְיָ אֱלָהָךְ לְפַרְעֹה וּלְכָל מִצְרָיִם:
@8 נִסִין רַבְרְבִין דִי חֲזָאָה עֵינָךְ וְאָתַיָא וּמוֹפְתַיָא וִידָא תַקֶפְתָּא וּדְרָעָא מְרָמְמָא דִי אַפְּקָךְ יְיָ אֱלָהָךְ כֵּן יַעְבֵּד יְיָ אֱלָהָךְ לְכָל עַמְמַיָא דִי אַתְּ דָחֵל מִקֳדָמֵיהוֹן:
@9 וְאַף יָת עֲרָעִיתָא יְגָרֵי יְיָ אֱלָהָךְ בְּהוֹן עַד דְיֵבַדוּן דְאִשְׁתָּאָרוּ וּדְאִטַמָרוּ מֵקֳדָמָךְ:
@10 לָא תִתְּבַר מִקֳדָמֵיהוֹן אֲרֵי יְיָ אֱלָהָךְ שְׁכִנְתֵּהּ בֵּינָךְ אֱלָהָא רַבָּא וּדְחִילָא:
@11 וִיתָרַךְ יְיָ אֱלָהָךְ יָת עַמְמַיָא הָאִלֵין מִקֳדָמָךְ זְעֵר זְעֵר לָא תִכּוּל לְשֵׁצָי וּתְהוֹן בִּפְרִי עַ דִי לְמָא תִסְגֵּי עֲלָךְ חֵיוַת בָּרָא:
@12 וְיִמְסְרִנוּן יְיָ אֱלָהָךְ קֳדָמָךְ וִישַׁגֵשִׁנוּן שִׁגוּשׁ רַב עַד דְיִשְׁתֵּצוּן:
@13 וְיִמְסַר מַלְכֵיהוֹן בִּידָךְ וְתוֹבַד יָת שִׁמְהוֹן מִתְּחוֹת שְׁמַיָא לָא יִתְעַתַּד אֱנַשׁ קֳדָמָךְ עַד דִתְשֵׁיצֵי יָתְהוֹן:
@14 צַלְמֵי טַעֲוָתְהוֹן תּוֹקְדוּן בְּנוּרָא לָא תַחְמֵד כַּסְפָּא וְדַהֲבָא דִי עֲלֵיהוֹן וְתִסַב לָךְ דִילְמָא תִּתָּקַל בֵּהּ אֲרֵי מְרָחָקָא דַיְיָ אֱלָהָךְ הוּא:
@15 וְלָא תָעֵל דִמְרָחָק לְבֵיתָךְ וּתְהֵי חֶרְמָא כְּוָתֵהּ שַׁקָצָא תְשַׁקְצִנֵהּ וְרַחָקָא תְּרַחֲקִנֵהּ אֲרֵי חֶרְמָה הוּא:
@16 כָּל תַּפְקֶדְתָּא דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין תִּטְרוּן לְמֶעְבָּד בְּדִיל דְתֵיחוּן וְתִסְגוּן וְתֵיתוּן וְתֵירְתוּן יָת אַרְעָא דִי קַיִים יְיָ לַאֲבָהָתְכוֹן:
@17 וְתִדְכַּר יָת כָּל אָרְחָא דִי דַבְּרָךְ יְיָ אֱלָהָךְ דְנַן אַרְבְּעִין שְׁנִין בְּמַדְבְּרָא בְּדִיל לְעַנָיוּתָךְ לְנַסָיוּתָךְ לְמִדַע יָת דִי בְלִבָּךְ הֲתִטַר פִּקוּדוֹהִי אִם לָא:
@18 וְעַנְיָךְ וְאַכְפָּנָךְ וְאוֹכָלָךְ יָת מַנָא דִי לָא יְדַעְתְּ וְלָא יָדְעוּן אֲבָהָתָיךְ בְּדִיל לְאוֹדָעוּתָךְ אֲרֵי לָא עַל לַחְמָא בִלְחוֹדוֹהִי מִתְקַיַם אֱנָשָׁא אֲרֵי עַל כָּל אַפָּקוּת מֵימְרָא דַיְיָ יִתְקַיַם אֱנָשָׁא:
@19 כְּסוּתָךְ לָא אִבְלִיאַת מִנָךְ וּמְסָנָךְ לָא יְחֵפוּ דְנַן אַרְבְּעִין שְׁנִין:
@20 וְתִדַע עִם לִבָּךְ אֲרֵי כְּמָא דִי מְאַלֵף גַבְרָא יָת בְּרֵהּ יְיָ אֱלָהָךְ מְאַלֵף לָךְ:
@21 וְתִטַר יָת פִּקוּדַיָא דַיְיָ אֱלָהָךְ לִמְהַךְ בְּאָרְחַן דְתַקְנָן קֳדָמוֹהִי וּלְמִדְחַל יָתֵהּ:
@22 אֲרֵי יְיָ אֱלָהָךְ מַעֲלָךְ לְאַרְעָא טַבְתָא אַרְעָא נָגְדָא נַחֲלִין דְמַיִין מַבּוּעֵי עֵינַוָן וּתְהוֹמִין נָפְקִין בְּבִקְעָן וּבְטוּרִין:
@23 אַרְעָא חִטִּין וְסַעֲרִין וְגוּפְנִין וּתְאֵנִין וְרִמוֹנִין אַרְעָא דְזֵיתָהָא עָבְדִין מִשְׁחָא וְהִיא עָבְדָא דְבָשׁ:
@24 אַרְעָא דִי לָא בְעִצוּרִין (נ''א בְמִסְכֵּנוּ) תֵּיכוּל בַּהּ לַחֲמָא לָא תֶחְסַר כָּל מִדַעַם בַּהּ אַרְעָא דִי אַבְנָהָא פַרְזְלָא וּמִטוּרָהָא תִּפְסוּל נְחָשָׁא:
@25 וְתֵיכוּל וְתִשְׂבַּע וּתְבָרַךְ יָת יְיָ אֱלָהָךְ עַל אַרְעָא טַבְתָא דִיהַב לָךְ:
@26 אִסְתַּמַר לָךְ דִילְמָא תִתְנְשֵׁי יָת דַחַלְתָּא דַיְיָ אֱלָהָךְ בְּדִיל דְלָא לְמִטַר פִּקּוֹדוֹהִי וְדִינוֹהִי וּקְיָמוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין:
@27 דִילְמָא תֵיכוּל וְתִשְׂבַּע וּבָתִּין שַׁפִּירִין תִּבְנֵי וְתֵיתֵב:
@28 וְתוֹרָךְ וְעָנָךְ יִסְגוּן וְכַסְפָּא וְדַהֲבָא יִסְגֵא לָךְ וְכֹל דִי לָךְ יִסְגֵא:
@29 וִירִים לִבָּךְ וְתִנְשֵׁי יָת דַחַלְתָּא דַיְיָ אֱלָהָךְ דִי אַפְּקָךְ מֵאַרְעָא דְמִצְרַיִם מִבֵּית עַבְדוּתָא:
@30 דְדַבְּרָךְ בְּמַדְבְּרָא רַבָּא וּדְחִילָא אֲתַר חֵיוָן קָלָן וְעַקְרַבִּין וּבֵית צַחֲוָנָא אֲתַר דִי לֵית מַיָא דְאַפֵּק לָךְ מַיָא מִטִּנָרָא תַּקִיפָא:
@31 דְאוֹכָלָךְ מַנָא בְּמַדְבְּרָא דִי לָא יָדְעוּן אֲבָהָתָךְ בְּדִיל לְעַנָיוּתָךְ וּבְדִיל לְנַסָיוּתָךְ לְאוֹטָבָא לָךְ בְּסוֹפָךְ:
@32 וְתֵימַר בְּלִבָּךְ חֵילִי וּתְקֵף יְדִי קְנוֹ לִי יָת נִכְסַיָא הָאִלֵין:
@33 וְתִדְכַּר יָת יְיָ אֱלָהָךְ אֲרֵי הוּא יָהֵב לָךְ עֵצָה לְמִקְנֵי נִכְסִין בְּדִיל לְקַיָמָא יָת קְיָמֵהּ דִי קַיִים לְאֲבָהָתָךְ כְּיוֹמָא הָדֵין:
@34 וִיהֵי אִם מִנְשָׁאָה תִנְשֵׁי יָת דַחַלְתָּא דַיְיָ אֱלָהָךְ וּתְהַךְ בָּתַר טַעְוַת עַמְמַיָא וְתִפְלְחִנוּן וְתִסְגוּד לְהוֹן אַסְהֵדִית בְּכוֹן יוֹמָא דֵין אֲרֵי מֵיבַד תֵּיבְדוּן:
@35 כְּעַמְמַיָא דִי יְיָ מֹאבִיד מִקֳדָמֵיכוֹן כֵּן תֵּיבְדוּן חֳלַף דְלָא קַבֶּלְתּוּן בְּמֵימְרָא דַיְיָ אֱלָהֲכוֹן:
@36 שְׁמַע יִשְׂרָאֵל אַתְּ עָבֵר יוֹמָא דֵין יָת יַרְדְנָא לְמֵיעַל לְמֵירַת עַמְמִין רַבְרְבִין וְתַקִיפִין מִנָךְ קִרְוִין רַבְרְבָן וּכְרִיכָן עַד צֵית שְׁמַיָא:
@37 עַם רַב וְתַקִיף בְּנֵי גִבָּרַיָא דִי אַתְּ יְדַעַתְּ וְאַתְּ שְׁמַעְתְּ מָן יִכּוּל לְמֵיקַם קֳדָם בְּנֵי גִבָּרַיָא:
@38 וְתִדַע יוֹמָא דֵין אֲרֵי יְיָ אֱלָהָךְ הוּא דְעֲבַר קֳדָמָךְ מֵימְרֵהּ אֶשָׁא אָכְלָא הוּא יְשֵׁצִנוּן וְהוּא יְתָרֵכִנוּן קֳדָ מָךְ וּתְתָרֵ כִנוּן וְתוֹבְדִנוּן בִּפְרִיעַ כְּמָא דִי מַלִיל יְיָ לָךְ:
@39 לָא תֵימַר בְּלִבָּךְ בִּדְיִתְּבַר יְיָ אֱלָהָךְ יָתְהוֹן מִקֳדָמָךְ לְמֵימַר בְּזָכוּתִי אַעֲלַנִי יְיָ לְמֵירַת יָת אַרְעָא הָדָא וּבְחוֹבֵי עַמְמַיָא הָאִלֵין יְיָ מְתָרֶכְהוֹן מֵקֳדָמָךְ:
@40 לָא בְזָכוּתָךְ וּבְקַשִׁיטּוּת לִבָּךְ אַתְּ עָלֵל לְמֵירַת יָת אַרְעֲהוֹן אֲרֵי בְּחוֹבֵי עַמְמַיָא הָאִלֵין יְיָ אֱלָהָךְ מתָרֶכְהוֹן מִקָדָמָךְ וּבְדִיל לַאֲקָמָא יָת פִּתְגָמָא דִי קַיִים יְיָ לַאֲבָהָתָךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב:
@41 וְתִדַע אֲרֵי לָא בְזָכוּתָךְ יְיָ אֱלָהָךְ יָהֵב לָךְ יָת אַרְעָא טַבְתָא הָדָא לְמֵירְתַהּ אֲרֵי עַם קְשֵׁי קְדַל אַתְּ:
@42 הֱוֵי דְכִיר לָא תִנְשֵׁי יָת דִי אַרְגֶזְתָּא קֳדָם יְיָ אֱלָהָךְ בְּמַדְבְּרָא לְמִן יוֹמָא דִי נְפַקְתָּא מֵאַרְעָא דְמִצְרַיִם עַד מֵיתֵיכוֹן עַד אַתְרָא הָדֵין מְסָרְבִין הֲוֵיתוּן קֳדָם יְיָ:
@43 וּבְחוֹרֵב אַרְגֶזְתּוּן קֳדָם יְיָ וַהֲוָה רְגַז מִן קֳדָם יְיָ בְּכוֹן לְשֵׁיצָאָה יַתְכוֹן:
@44 בְּמִסְקִי לְטוּרָא לְמִסַב לוּחֵי אַבְנַיָא לוּחֵי קְיָמָא דִי גְזַר יְיָ עִמְכוֹן וִיתֵבִית בְּטוּרָא אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן לַחֲמָא לָא אֲכָלִית וּמַיָא לָא אִשְׁתֵּיתִי:
@45 וִיהַב יְיָ לִי יָת תְּרֵין לוּחֵי אַבְנַיָא כְּתִיבִין בְּאֶצְבְּעָא דַיְיָ וַעֲלֵיהוֹן כְּכָל פִּתְגָמַיָא דִי מַלִיל יְיָ עִמְכוֹן בְּטוּרָא מִגוֹ אֶשָׁתָא בְּיוֹמָא דִקְהָלָא:
@46 וַהֲוָה מִסוֹף אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן יְהַב יְיָ לִי יָת תְּרֵין לוּחֵי אַבְנַיָא לוּחֵי קְיָמָא:
@47 וַאֲמַר יְיָ לִי קוּם חוּת בִּפְרִיעַ מִכָּא אֲרֵי חַבִּיל עַמָךְ דִי אַפֶּקְתָּא מִמִצְרָיִם סָטוּ בִּפְרִיעַ מִן אָרְחָא דִי פַקֶדְתִּנוּן עֲבָדוּ לְהוֹן מַתְּכָא:
@48 וַאֲמַר יְיָ לִי לְמֵימָר גְלֵי קֳדָמַי יָת עַמָא הָדֵין וְהָא עַם קְשֵׁי קְדַל הוּא:
@49 אַנַח בָּעוּתָךְ מִקֳדָמַי וֶאֱשֵׁצִנוּן וְאֶמְחֵי יָת שִׁמְהוֹן מִתְּחוֹת שְׁמַיָא וְאֶעְבֵּד יָתָךְ לְעַם תַּקִיף וְסַגִי מִנְהוֹן:
@50 וְאִתְפְּנֵיתִי וּנְחָתִית מִן טוּרָא וְטּוּרָא בָּעֵר בְּאֶשָׁתָא וּתְרֵין לוּחֵי קְיָמָא עַל תַּרְתֵּין יְדָי:
@51 וַחֲזֵיתִי וְהָא חַבְתּוּן קֳדָם יְיָ אֱלָהֲכוֹן עֲבַדְתּוּן לְכוֹן עֵגֶל מַתְּכָא סְטֵיתוּן בִּפְרִיעַ מִן אָרְחָא דִי פַקִיד יְיָ יָתְכוֹן:
@52 וַאֲחָדִית בִּתְרֵין לוּחַיָא וּרְמִיתִנוּן מֵעַל תַּרְתֵּין יְדָי וּתְבַרְתִּנוּן לְעֵינֵיכוֹן:
@53 וְאִשְׁתַּטָחִית קֳדָם יְיָ כְּקַדְמֵיתָא אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן לַחְמָא לָא אֲכָלִית וּמַיָא לָא אִשְׁתֵּיתִי עַל כָּל חוֹבֵיכוֹן דִי חַבְתּוּן לְמֶעְבַּד דְבִישׁ קֳדָם יְיָ לְאַרְגָזָא קֳדָמוֹהִי:
@54 אֲרֵי דְחֵלִית מִקָדָם רָגְזָא וְחֵמְתָא דִי רְגַז יְיָ עֲלֵיכוֹן לְשֵׁצָאָה יָתְכוֹן וְקַבִּיל יְיָ צְלוֹתִי אַף בְּזִמְנָא הַהִיא:
@55 וְעַל אַהֲרֹן הֲוָה רְגַז מִן קֳדָם יְיָ לַחֲדָא לְשֵׁצָיוּתֵהּ וְצַלֵיתִי אַף עַל אַהֲרֹן בְּעִדָנָא הַהִיא:
@56 וְיָת חוֹבָתְכוֹן דִי עֲבַדְתּוּן יָת עֶגְלָא נְסֵבִית וְאוֹקֵדִית יָתֵהּ בְּנוּרָא וְשָׁפִית יָתֵהּ בְּשׁוּפִינָא יָאוּת עַד דִי הֲוָה דַקִיק לְעַפְרָא וּרְמֵת יָת עַפְרֵהּ לְנַחֲלָא דְנָחֵת מִן טוּרָא:
@57 וּבִדְלֶקְתָּא וּבְנִסֵתָא וּבְקִבְרֵי דִמְשַׁאֲלֵי מַרְגְזִין הֲוֵיתוּן קֳדָם יְיָ:
@58 וְכַד שְׁלַח יְיָ יָתְכוֹן מֵרְקַם גֵיאָה לְמֵימַר סְקוֹ וְאַחֲסִינוּ יָת אַרְעָא דִי יְהָבִית לְכוֹן וְסָרֶבְתּוּן עַל גְזֵרַת מֵימְרָא דַיְיָ אֱלָהֲכוֹן וְלָא הֵימַנְתּוּן לֵהּ וְלָא קַבֶּלְתּוּן לְמֵימְרֵהּ:
@59 מְסָרְבִין הֲוֵיתוּן קֳדָם יְיָ מִיוֹמָא דִידָעִית יָתְכוֹן:
@60 וְאִשְׁתַּטָחִית קֳדָם יְיָ יָת אַרְבְּעִין יְמָמִין וְיָת אַרְבְּעִין לֵילָוָן דִי אִשְׁתַּטָחִית אֲרֵי אֲמַר יְיָ לְשֵׁצָאָה יָתְכוֹן:
@61 וְצַלֵיתִי קֳדָם יְיָ וַאֲמָרִית יְיָ אֱלֹהִים לָא תְחַבֵּל עַמָךְ וְאַחֲסַנְתָּךְ דִי פְרַקְתָּא בְּתָקְפָּךְ דִי אַפֶּקְתָּא מִמִצְרַיִם בִּידָא תַקִיפָא:
@62 אִדְכַר לְעַבְדָיךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב לָא תִתְפְּנֵי לְקַשְׁיוּת עַמָא הָדֵין וּלְחוֹבֵיהוֹן וְלַחֲטָאֵיהוֹן:
@63 דִילְמָא יֵימְרוּן דָיְרֵי אַרְעָא דִי אַפֶּקְתָּנָא מִתַּמָן מִדְלֵית יוּכְלָא דַיְיָ לְאָעָלוּתְהוֹן לְאַרְעָא דִי מַלִיל לְהוֹן וּמִדְסָנֵי יָתְהוֹן אַפֵּקִנוּן לְקַטָלוּתְהוֹן בְּמַדְבְּרָא:
@64 וְאִנוּן עַמָךְ וְאַחֲסַנְתָּךְ דִי אַפֶּקְתָּא בְּחֵילָךְ רַבָּא וּבִדְרָעָךְ מְרָמְמָא:
@65 בְּעִדָנָא הַהִיא אֲמַר יְיָ לִי פְּסַל לָךְ תְּרֵין לוּחֵי אַבְנַיָא כְּקַדְמָאֵי וְסַק לָקֳדָמַי לְטּוּרָא וְתַעְבֵּד לָךְ אֲרוֹנָא דְאָעָא:
@66 וְאֶכְתּוֹב עַל לוּחַיָא יָת פִּתְגָמַיָא דִי הֲווֹ עַל לוּחַיָא קַדְמָאֵי דִי תְבַרְתָּא וּתְשַׁוִנוּן בַּאֲרוֹנָא:
@67 וַעֲבָדִית אֲרוֹנָא דְאָעֵי שִׁטִּין וּפְסָלִית תְּרֵין לוּחֵי אַבְנַיָא כְּקַדְמָאֵי וּסְלֵקִית לְטוּרָא וּתְרֵין לוּחַיָא בִּידִי:
@68 וּכְתַב עַל לוּחַיָא כִּכְתָבָא קַדְמָאָה יָת עַשְׂרָא פִתְגָמַיָא דִי מַלִיל יְיָ עִמְכוֹן בְּטוּרָא מִגוֹ אֶשְׁתָא בְּיוֹמָא דִקְהָלָא וִיהָבִנוּן יְיָ לִי:
@69 וְאִתְפְּנֵיתִי וּנְחָתִית מִן טוּרָא וְשַׁוֵיתִי יָת לוּחַיָא בַּאֲרוֹנָא דִי עֲבָדִית וַהֲווֹ תַמָן כְּמָא דִי פַקְדַנִי יְיָ:
@70 וּבְנֵי יִשְׂרָאֵל נְטָלוּ מִבְּאֵרוֹת בְּנֵי יַעֲקָן לְמוֹסֵרָה תַּמָן מִית אַהֲרֹן וְאִתְקְבַר תַּמָן וְשַׁמֵשׁ אֶלְעָזָר בְּרֵהּ תְּחוֹתוֹהִי:
@71 מִתַּמָן נְטָּלוּ לְגֻדְגֹד וּמִן גֻדְגֹד לְיָטְבָת אַרְעָא נָגְדָא נַחֲלִין דְמַיִין:
@72 בְּעִדָנָא הַהִיא אַפְרֵשׁ יְיָ יָת שִׁבְטָּא דְלֵוִי לְמִטַל יָת אֲרוֹן קְיָמָא דַיְיָ לְמֵיקַם קֳדָם יְיָ לְשַׁמָשׁוּתֵהּ וּלְבָרָכָא בִשְׁמֵהּ עַד יוֹמָא הָדֵין:
@73 עַל כֵּן לָא הֲּוָה לְלֵוִי חֳלָק וְאַחֲסָנָא עִם אֲחוֹהִי מַתְּנָן דִיהַב לֵהּ יְיָ אִנוּן אַחֲסַנְתֵּהּ כְּמָא דִי מַלִיל יְיָ אֱלָהָךְ לֵהּ:
@74 וַאֲנָא הֲוֵיתִי קָאֵם בְּטוּרָא כְּיוֹמִין קַדְמָאִין אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן וְקַבִּיל יְיָ צְלוֹתִי אַף בְּזִמְנָא הַהוּא לָא אָבֵי יְיָ לְחַבָּלוּתָךְ:
@75 וַאֲמַר יְיָ לִי קוּם זִיל לְמִטוּל קֳדָם עַמָא וְיֵעֲלוּן וְיֵרְתוּן יָת אַרְעָא דִי קַיֵמִית לַאֲבָהָתְהוֹן לְמִתַּן לְהוֹן:
@76 וּכְעַן יִשְׂרָאֵל מָה יְיָ אֱלָהָךְ תָּבַע מִנָךְ אֱלָהֵן לְמִדְחַל קֳדָם יְיָ אֱלָהָךְ לִמְהַךְ בְּכָל אָרְחָן דְתָקְנָן קֳדָמוֹהִי וּלְמִרְחַם יָתֵהּ וּלְמִפְלַח קֳדָם יְיָ אֱלָהָךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@77 לְמִטַר יָת פִּקוֹדַיָא דַיְיָ וְיָת קְיָמוֹהִי דַאֲנָא מְפַקְדָךְ יוֹמָא דֵין לִדְיֵיטַב לָךְ:
@78 הָא דַיְיָ אֱלָהָךְ שְׁמַיָא וּשְׁמֵי שְׁמַיָא אַרְעָא וְכָל דִי בַהּ:
@79 לְחוֹד בַּאֲבָהָתָךְ צָבֵי יְיָ לְמִרְחַם יָתְהוֹן וְאִתִּרְעֵי בִּבְנֵיהוֹן בַּתְרֵיהוֹן בְּכוֹן מִכָּל עַמְמַיָא כְּיוֹמָא הָדֵין:
@80 וְתֶעְדוּן יָת טַפְשׁוּת לִבְּכוֹן וּקְדָלְכוֹן לָא תַקְשׁוּן עוֹד:
@81 אֲרֵי יְיָ אֱלָהֲכוֹן הוּא אֱלָהָא דַיָנִין וּמָרֵי מַלְכִין אֱלָהָא רַבָּא גִבָּרָא וּדְחִילָא דִי לֵית קֳדָמוֹהִי מִסַב אַפִּין וְאַף לָא לְקַבָּלָא שָׁחְדָא:
@82 עָבֵד דִין יִתַּם וְאַרְמְלָא וְרָחֵם גִיוֹרָא לְמִתַּן לֵהּ מְזוֹנָא וּכְסוּ:
@83 וְתִרְחֲמוּן יָת גִיוֹרָא אֲרֵי דַיָרִין הֲוֵיתוּן בְּאַרְעָא דְמִצְרָיִם:
@84 יָת יְיָ אֱלָהָךְ תִּדְחַל וְקָדָמוֹהִי תִפְלָח וּלְדַחַלְתֵּהּ תִּקְרַב וּבִשְׁמֵהּ תְּקַיַם:
@85 הוּא תֻשְׁבַּחְתָּךְ וְהוּא אֱלָהָךְ דַעֲבַד עִמָךְ יָת רַבְרְבָתָא וְיָת חֲסִינָתָא הָאִלֵין דִי חֲזוֹ עֵינָיךְ:
@86 בְּשַׁבְעִין נַפְשָׁן נְחָתוּ אֲבָהָתָךְ לְמִצְרָיִם וּכְעַן שַׁוְיָךְ יְיָ אֱלָהָךְ כְּכוֹכְבֵי שְׁמַיָא לְמִסְגֵי:
@87 וְתִרְחַם יָת יְיָ אֱלָהָךְ וְתִטַּר מַטְרַת מֵימְרֵהּ וּקְיָמוֹהִי וְדִינוֹהִי וּפִקוֹדוֹהִי כָּל יוֹמַיָא:
@88 וְתִדְעוּן יוֹמָא דֵין אֲרֵי לָא יָת בְּנֵיכוֹן דִי לָא יְדָעוּ וְדִי לָא חֲזוֹ יָת אֻלְפָנָא דַיְיָ אֱלָהֲכוֹן יָת רְבוּתֵהּ יָת יְדֵהּ תַּקִיפָא וּדְרָעֵהּ מְרָמְמָא:
@89 וְיָת אַתְוָתֵהּ וְיָת עוֹבָדוֹהִי דִי עֲבַד בְּגוֹ מִצְרָיִם לְפַרְעֹה מַלְכָּא דְמִצְרַיִם וּלְכָל אַרְעֵהּ:
@90 וְדִי עֲבַד לְמַשִׁרְיַת מִצְרַיִם לְסוּסְוָתֵהּ וְלִרְתִיכוֹהִי דִי אַטִיף יָת מֵי יַמָא דְסוּף עַל אַפֵּיהוֹן בְּמִרְדָפְהוֹן בַּתְרֵיכוֹן וְאוֹבָדִנוּן יְיָ עַד יוֹמָא הָדֵין:
@91 וְדִי עֲבַד לְכוֹן בְּמַדְבְּרָא עַד מֵיתֵיכוֹן עַד אַתְרָא הָדֵין:
@92 וְדִי עֲבַד לְדָתָן וְלַאֲבִירָם בְּנֵי אֱלִיאָב בַּר רְאוּבֵן דִי פְתָחַת אַרְעָא יָת פּוּמַהּ וּבְלָעָתְנוּן וְיָת אֱנַשׁ בָּתֵּיהוֹן וְיָת מַשְׁכְּנֵיהוֹן וְיָת כָּל יְקוּמָא דִי עִמְהוֹן בְּגוֹ כָּל יִשְׂרָאֵל:
@93 אֲרֵי עֵינֵיכוֹן חֲזָאָן יָת כָּל עוֹבָדָא דַיְיָ רַבָּא דִי עֲבָד:
@94 וְתִטְרוּן יָת כָּל תַּפְקֶדְתָּא דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין בְּדִיל דְתִתְקְפוּן וְתֵעֲלוּן וְתֵירְתוּן יָת אַרְעָא דִי אַתּוּן עָבְרִין תַּמָן לְמֵירְתַהּ:
@95 וּבְדִיל דְתוֹרְכוּן יוֹמִין עַל אַרְעָא דִי קַיִים יְיָ לַאֲבָהָתְכוֹן לְמִתַּן לְהוֹן וְלִבְנֵיהוֹן אַרְעָא עָבְדָא חֲלַב וּדְבָשׁ:
@96 אֲרֵי אַרְעָא דִי אַתְּ עָלֵל לְתַמָן לְמֵירְתַהּ לָא כְאַרְעָא דְמִצְרַיִם הִיא דִי נְפַקְתּוּן מִתַּמָן דִי תִזְרַע יָת זַרְעָךְ וּמַשְׁקַת לֵהּ בְּרַגְלָךְ כְּגִנְתָא יַרְקָא:
@97 וְאַרְעָא דִי אַתּוּן עָבְרִין תַּמָן לְמֵירְתַהּ אֲרַע טוּרִין וּבִקְעָן לִּמְטַּר שְׁמַיָא תִּשְׁתֵּי מַיָא:
@98 אַרְעָא דַיְיָ אֱלָהָךְ תָּבַע יָתַהּ תְּדִירָא עֵינֵי דַיְיָ אֱלָהָךְ בַּהּ מֵרֵישָׁא דְשַׁתָּא וְעַד סוֹפָא דְשַׁתָּא:
@99 וִיהֵי אִם קַבָּלָא תְקַבְּלוּן לְפִקוּדַי דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין לְמִרְחַם יָת יְיָ אֱלָהֲכוֹן וּלְמִפְלַח קֳדָמוֹהִי בְּכָל לִבְּכוֹן וּבְכָל נַפְשְׁכוֹן:
@100 וְאֶתֵּן מְטַר אַרְעֲכוֹן בְּעִדָנֵהּ בַּכִּיר וְלַקִישׁ וְתִכְנוֹשׁ עִבוּרָךְ וְחַמְרָךְ וּמִשְׁחָךְ:
@101 וְאֶתֵּן עִשְׂבָּא בְחַקְלָךְ לִבְעִירָךְ וְתֵיכוּל וְתִשְׂבָּע:
@102 אִסְתַּמָרוּ לְכוֹן דִילְמָא יִטְעוּן לִבְּכוֹן וְתִסְטוּן וְתִפְלְחוּן לְטַעֲוַת עַמְמַיָא וְתִסְגְדוּן לְהוֹן:
@103 וְיִתְקוֹף רָגְזָא דַיְיָ בְּכוֹן וְיֵחוֹד יָת שְׁמַיָא וְלָא יְהֵי מִטְרָא וְאַרְעָא לָא תִתֵּן יָת עֲלַלְתַּהּ וְתֵיבְדוּן בִּפְרִיעַ מֵעַל אַרְעָא טַבְתָא דַיְיָ יָהֵב לְכוֹן:
@104 וּתְשַׁווּן יָת פִּתְגָמַי אִלֵין עַל לִבְּכוֹן וְעַל נַפְשְׁכוֹן וְתִקְטְרוּן יָתְהוֹן לְאָת עַל יֶדְכוֹן וִיהוֹן לִתְפִלִין בֵּין עֵינֵיכוֹן:
@105 וְתַלְפוּן יָתְהוֹן יָת בְּנֵיכוֹן לְמַלָלָא בְהוֹן בְּמִתְּבָךְ בְּבֵיתָךְ וּבִמְהָכָךְ בְּאָרְחָא וּבְמִשְׁכְּבָךְ וּבִמְקִימָךְ:
@106 וְתִכְתְּבִנוּן עַל מְזוּזְיָן וְתִקְבְּעִנוּן בְּסִפֵּי בֵיתָךְ וּבְתַרְעָיךְ:
@107 בְּדִיל דְיִסְגוּן יוֹמֵיכוֹן וְיוֹמֵי בְנֵיכוֹן עַל אַרְעָא דִי קַיִים יְיָ לַאֲבָהָתְכוֹן לְמִתַּן לְהוֹן כְּיוֹמֵי שְׁמַיָא עַל אַרְעָא:
@108 אֲרֵי אִם מִטַר תִּטְרוּן יָת כָּל תַּפְקֶדְתָּא הָדָא דִי אֲנָא מְפַקֵד יָתְכוֹן לְמֶעְבְּדַהּ לְמִרְחַם יָת יְיָ אֱלָהֲכוֹן לִמְהַךְ בְּכָל אָרְחָן דְתַקְנָן קֳדָמוֹהִי וּלְאִתְקְרָבָא לְדַחַלְתֵּהּ:
@109 וִיתָרֵךְ יְיָ יָת כָּל עַמְמַיָא הָאִלֵין מִקֳדָמֵיכוֹן וְתֵירְתוּן עַמְמִין רַבְרְבִין וְתַקִיפִין מִנְכוֹן:
@110 כָּל אַתְרָא דִי תִדְרוֹךְ פַּרְסַת רַגְלְכוֹן בֵּהּ דִלְכוֹן יְהֵי מִן מַדְבְּרָא וְלִבְנָן מִן נַהֲרָא נְהַר פְּרָת וְעַד יַמָא מַעַרְבָא יְהֵי תְחוּמְכוֹן:
@111 לָא יִתְעַתַּד אֱנָשׁ קֳדָמֵיכוֹן דַחֲלָתְכוֹן וְאֵימָתְכוֹן יִתֵּן יְיָ אֱלָהֲכוֹן עַל אַפֵּי כָל אַרְעָא דִי תִדְרְכוּן בַּהּ כְּמָה דִי מַלִיל לְכוֹן: ססס:

@1 **והיה עקב תשמעון.** אם המצות הקלות שאדם דש בעקביו תשמעון: **ושמר ה'** וגו' **.** ישמור לך הבטחתו:
@2 **שגר אלפיך.** ולדי בקרך, שהנקבה משגרת ממעיה: **ועשתרת צאנך.** מנחם פרש אבירי בשן (תהלים כב, יג) , מבחר הצאן. כמו (בראשית יד, ה) עשתרות קרנים, לשון חזק. ואונקלוס תרגם ועדרי ענך. ורבותינו אמרו למה נקרא שמם עשתרות שמעשירות את בעליהן:
@3 **עקר.** שאינו מוליד:
@6 **כי תאמר בלבבך.** על כרחך לשון דלמא הוא, שמא תאמר בלבבך מפני שהם רבים לא אוכל להורישם, אל תאמר כן, לא תירא מהם. ולא יתכן לפרשו באחת משאר לשונות של 'כי', שיפול עליו שוב לא תירא מהם:
@8 **המסות.** נסיונות: **והאותות.** כגון (שמות ד, ג) ויהי לנחש, (שמות ד, ט) והיו לדם ביבשת: **והמופתים.** המכות המפלאות: **והיד החזקה.** זה הדבר: **והזרוע הנטויה.** זה החרב של מכת בכורות:
@9 **הצרעה.** מין שרץ העוף, שהיתה זורקת בהם מרה ומסרסתן ומסמאה את עיניהם בכל מקום שהיו נסתרים שם:
@11 **פן תרבה עליך חית השדה.** והלא אם עושין רצונו של מקום אין מתיראין מן החיה, שנאמר (איוב ה, כג) וחית השדה השלמה לך, אלא גלוי היה לפניו שעתידין לחטוא:
@12 **והמם.** נקוד קמ''ץ כלו, לפי שאין מ''ם אחרונה מן היסוד, והרי הוא כמו והם אותם. אבל (ישעי' כח, כח) והמם גלגל עגלתו, כלו יסוד. לפיכך חציו קמ''ץ וחציו פת''ח, כשאר פעל של שלש אותיות:
@16 **כל המצוה.** כפשוטו. ומדרש אגדה אם התחלת במצוה גמור אותה, שאינה נקראת אלא על שם הגומרה, שנאמר (יהושע כד, לב) ואת עצמות יוסף אשר העלו בני ישראל ממצרים קברו בשכם, והלא משה לבדו נתעסק בהם להעלותם, אלא לפי שלא הספיק לגמרה וגמרוה ישראל, נקראת על שמם:
@17 **התשמר מצותיו.** שלא תנסהו ולא תהרהר אחריו:
@19 **שמלתך לא בלתה.** ענני כבוד היו שפים בכסותם ומגהצים אותם כמין כלים מגוהצים, ואף קטניהם כמו שהיו גדלים היה גדל לבושן עמהם, כלבוש הזה של חומט שגדל עמו: **לא בצקה.** לא נפחה כבצק, כדרך הולכי יחף שרגליהם נפוחות:
@23 **זית שמן.** זיתים העושים שמן:
@36 **גדלים ועצמים ממך.** אתה עצום, והם עצומים ממך:
@39 **אל תאמר בלבבך.** צדקתי ורשעת הגוים גרמו:
@40 **לא בצדקתך** וגו' **אתה בא לרשת** וגו' **כי ברשעת הגוים.** הרי כי משמש בלשון אלא:
@44 **ואשב בהר.** אין ישיבה אלא לשון עכבה:
@46 **לחת.** לחת כתיב, ששתיהם שוות:
@53 **ואתנפל לפני ה' כראשנה ארבעים יום.** שנאמר (שמות לב, ל) ועתה אעלה אל ה' אולי אכפרה. באותה עליה נתעכבתי ארבעים יום. נמצאו כלים בעשרים ותשעה באב. שהוא עלה בשמונה עשר בתמוז, בו ביום נתרצה הקדוש ברוך הוא לישראל ואמר לו למשה (דברים י, א) פסל לך שני לוחת, עשה עוד ארבעים יום, נמצאו כלים ביום הכפורים. בו ביום נתרצה הקדוש ברוך הוא לישראל בשמחה ואמר לו למשה (במדבר יד, כ) סלחתי כדברך. לכך הקבע למחילה ולסליחה. ומנין שנתרצה ברצון שלם, שנאמר בארבעים של לוחות אחרונות ואנכי עמדתי בהר כימים הראשונים (דברים י, י) , מה הראשונים ברצון אף אחרונים ברצון, אמור מעתה אמצעיים היו בכעס:
@55 **ובאהרן התאנף ה'.** לפי ששמע לכם: **להשמידו.** זה כלוי בנים. וכן הוא אומר (עמוס ב, ט) ואשמיד פריו ממעל: **ואתפלל גם בעד אהרן.** והועילה תפלתי לכפר מחצה, ומתו שנים ונשארו השנים:
@56 **טחון.** לשון הוה כמו (בראשית כו, יג) הלוך וגדל:
@60 **ואתנפל** וגו' **.** אלו הן עצמם האמורים למעלה (פסוק יח) וכפלן כאן, לפי שכתוב כאן סדר תפלתו, שנאמר (פסוק כו) ה' אלהים אל תשחת עמך וגו' :
@65 **בעת ההוא.** לסוף ארבעים יום נתרצה לי ואמר לי פסל לך, ואחר כך ועשית לך ארון עץ, ואני עשיתי ארון תחלה, שכשאבוא והלחות בידי היכן אתנם. ולא זה הוא הארון שעשה בצלאל, שהרי משכן לא נתעסקו בו עד לאחר יום הכפורים, כי ברדתו מן ההר צוה להם על מלאכת המשכן, ובצלאל עשה משכן תחלה ואחר כך ארון וכלים, נמצא זה ארון אחר היה. וזהו שהיה יוצא עמהם למלחמה. ואותו שעשה בצלאל לא יצא למלחמה אלא בימי עלי, ונענשו עליו ונשבה:
@70 **ובני ישראל נסעו מבארות בני יעקן מוסרה.** מה ענין זה לכאן. ועוד, וכי מבארות בני יעקן נסעו למוסרה, והלא ממוסרות באו לבני יעקן, שנאמר (במדבר לג, לא) ויסעו ממוסרות וגו' . ועוד, שם מת אהרן, והלא בהר ההר מת, צא וחשוב ותמצא שמונה מסעות ממוסרה להר ההר. אלא, אף זו מן התוכחה, ועוד זאת עשיתם כשמת אהרן בהר ההר לסוף ארבעים שנה ונסתלקו ענני כבוד, יראתם לכם ממלחמת מלך ערד ונתתם ראש לחזור למצרים, וחזרתם לאחוריכם שמונה מסעות עד בני יעקן ומשם למוסרה, שם נלחמו בכם בני לוי והרגו מכם ואתם מהם, עד שהחזירו אתכם בדרך חזרתכם, ומשם חזרתם הגדגדה הוא חור הגדגד:
@71 **ומן הגדגדה** וגו' **.** ובמוסרה עשיתם אבל כבד על מיתתו של אהרן שגרמה לכם זאת, ונדמה לכם כאלו מת שם. וסמך משה תוכחה זו לשבירת הלוחות, לומר שקשה מיתתן של צדיקים לפני הקדוש ברוך הוא, כיום שנשתברו בו הלוחות. ולהודיעך שהקשה לו מה שאמרו (במד' יד, ד) נתנה ראש לפרוש ממנו, כיום שעשו בו את העגל:
@72 **בעת ההוא הבדיל ה'** וגו' **.** מוסב לענין הראשון: **בעת ההוא.** בשנה הראשונה לצאתכם ממצרים וטעיתם בעגל ובני לוי לא טעו, הבדילם המקום מכם. וסמך מקרא זה לחזרת בני יעקן לומר שאף בזו לא טעו בה בני לוי, אלא עמדו באמונתם: **לשאת את ארון.** הלוים: **לעמד לפני ה' לשרתו ולברך בשמו.** הכהנים, והוא נשיאת כפים:
@73 **על כן לא היה ללוי חלק.** לפי שהבדלו לעבודת מזבח ואינן פנויין לחרוש ולזרוע: **ה' הוא נחלתו.** נוטל פרס מזמן מבית המלך:
@74 **ואנכי עמדתי בהר.** לקבל הלוחות האחרונות. ולפי שלא פרש למעלה כמה עמד בהר בעליה אחרונה זו, חזר והתחיל בה: **כימים הראשונים.** של לוחות הראשונות, מה הם ברצון אף אלו ברצון. אבל האמצעיים שעמדתי שם להתפלל עליכם היו בכעס:
@75 **ויאמר ה' אלי** וגו' **.** אף על פי שסרתם מאחריו וטעיתם בעגל, אמר לי (שמות לב, לד) לך נחה את העם:
@76 **ועתה ישראל.** אף על פי שעשיתם כל זאת, עודנו רחמיו וחבתו עליכם, ומכל מה שחטאתם לפניו אינו שואל מכם כי אם ליראה וגו' : **כי אם ליראה** וגו' **.** רבותינו דרשו מכאן, הכל בידי שמים חוץ מיראת שמים:
@77 **לשמר את מצות ה'.** ואף היא לא לחנם, אלא לטוב לך, שתקבלו שכר:
@78 **הן לה' אלהיך.** הכל, ואף על פי כן רק באבותיך חשק ה' מן הכל:
@79 **בכם.** כמו שאתם רואים אתכם חשוקים מכל העמים היום הזה:
@80 **ערלת לבבכם.** אוטם לבבכם וכסויו:
@81 **ואדני האדנים.** לא יוכל שום אדון להציל אתכם מידו: **לא ישא פנים.** אם תפרקו עלו: **ולא יקח שחד.** לפיסו בממון:
@82 **עשה משפט יתום ואלמנה.** הרי גבורה, ואצל גבורתו אתה מוצא ענותנותו: **ואהב גר לתת לו לחם ושמלה.** ודבר חשוב הוא זה, שכל עצמו של יעקב אבינו על זה נתפלל, (בראשית כח, כ) ונתן לי לחם לאכל ובגד ללבש:
@83 **כי גרים הייתם.** מום שבך אל תאמר לחברך:
@84 **את ה' אלהיך תירא.** ותעבוד לו ותדבק בו, ולאחר שיהיו בך כל המדות הללו, אז בשמו תשבע:
@88 **וידעתם היום.** תנו לב לדעת ולהבין ולקבל תוכחתי: **כי לא את בניכם.** אני מדבר עכשיו שיוכלו לומר אנו לא ידענו ולא ראינו בכל זה:
@92 **בקרב כל ישראל.** כל מקום שהיה אחד מהם בורח, הארץ נבקעת מתחתיו ובולעתו, אלו דברי רבי יהודה. אמר לו רבי נחמיה, והלא כבר נאמר (במדבר טז, לב) ותפתח הארץ את פיה, ולא פיותיה. אמר לו, ומה אני מקים בקרב כל ישראל. אמר לו שנעשית הארץ מדרון כמשפך, וכל מקום שהיה אחד מהם [בורח] , היה מתגלגל ובא עד מקום הבקיעה: **ואת כל היקום אשר ברגליהם.** זה ממונו של אדם שמעמידו על רגליו:
@93 **כי עיניכם הראת.** מוסב על מקרא האמור למעלה, (פסוק ב) כי לא את בניכם אשר לא ידעו וגו' כי אם עמכם אשר עיניכם הרואות וגו' :
@96 **לא כארץ מצרים הוא.** אלא טובה המנה. ונאמרה הבטחה זו לישראל ביציאתם ממצרים, שהיו אומרים שמא לא נבוא אל ארץ טובה ויפה כזו. יכול בגנותה הכתוב מדבר, וכך אמר להם, לא כארץ מצרים היא, אלא רעה המנה, תלמוד לומר (במדבר יג, כב) וחברון שבע שנים נבנתה וגו' , אדם אחד בנאן, וחם בנה צוען למצרים בנו, וחברון לכנען. דרך ארץ אדם בונה את הנאה ואחר כך בונה את הכעור שפסלתו של ראשון, הוא נותן בשני. ובכל מקום, החביב קודם. הא למדת שחברון יפה מצוען, ומצרים משבחת מכל הארצות, שנאמר (בראשית יג, י) כגן ה' כארץ מצרים, וצוען שבח מצרים היא, שהיתה מקום מלכות, שכן הוא אומר (ישעיה ל, ד) כי היו בצוען שריו. וחברון פסלתה של ארץ ישראל, לכך הקצוה לקבורת מתים, ואף על פי כן היא יפה מצוען. ובמסכת כתבות (קיב, א) דרשו בענין אחר, אפשר אדם בונה בית לבנו הקטן ואחר כך לבנו הגדול, אלא שמבנה על אחד משבעה בצוען: **אשר יצאתם משם.** אפלו ארץ רעמסס [וארץ גושן] אשר ישבתם בה והיא במיטב ארץ מצרים שנאמר (בראשית מז, יא) במיטב הארץ וגו' , אף היא אינה כארץ ישראל: **והשקית ברגלך.** ארץ מצרים היתה צריכה להביא מים מנילוס ברגלך ולהשקותה וצריך אתה לנדד משינתך ולעמול, והנמוך שותה ולא הגבוה, ואתה מעלה המים מן הנמוך לגבוה. אבל זו (פסוק יא) למטר השמים תשתה מים. אתה ישן על מטתך, והקדוש ברוך הוא משקה נמוך וגבוה, גלוי ושאינו גלוי, כאחת: **כגן הירק.** שאין די לו בגשמים ומשקין אותו ברגל ובכתף:
@97 **ארץ הרים ובקעת.** משבח ההר מן המישור, שהמישור, בבית כור אתה זורע כור, אבל ההר בבית כור ממנו חמשת כורין, ארבע מארבע שפועיו, ואחד בראשו: **ובקעת.** הן מישור:
@98 **אשר ה' אלהיך דרש אתה.** והלא אף כל הארצות הוא דורש, שנאמר (איוב לח, כו) להמטיר על ארץ לא איש, אלא כביכול אינו דורש אלא אותה, ועל ידי אותה דרישה שדורשה דורש את כל הארצות עמה: **תמיד עיני ה' אלהיך בה.** לראות מה היא צריכה ולחדש לה גזרות, עתים לטובה עתים לרעה וכו' , כדאיתא בראש השנה (יז, ב) : **מרשית השנה.** מראש השנה נדון מה יהא בסופה:
@99 **והיה אם שמע.** והיה, מוסב על האמור למעלה, (פסוק יא) למטר השמים תשתה מים: **והיה אם שמע תשמעו.** אם שמע בישן תשמעו בחדש. וכן (דברים ח, יט) והיה אם שכח תשכח, אם התחלת לשכח, סופך שתשכח כלה, שכן כתיב במגלה אם תעזבני יום, יומים אעזבך [ במגילת חסידים ] (ספרי מח) : **מצוה אתכם היום.** שיהיו עליכם חדשים, כאלו שמעתם בו ביום: **לאהבה את ה'.** שלא תאמר הרי אני לומד בשביל שאהיה עשיר, בשביל שאקרא רב, בשביל שאקבל שכר. אלא כל מה שתעשו עשו מאהבה וסוף הכבוד לבא: **ולעבדו בכל לבבכם.** עבודה שהיא בלב. וזו היא תפלה, שהתפלה קרויה עבודה, שנאמר (דניאל ו, יז) אלהך די אנת פלח לה בתדירא, וכי יש פלחן בבבל, אלא על שהיה מתפלל, שנאמר (שם ו, יא) וכוין פתיחן לה וגו' . וכן בדוד הוא אומר (תהלים קמא, ב) תכון תפלתי קטרת לפניך: **בכל לבבכם ובכל נפשכם.** והלא כבר הזהיר על כך (דברים ו, ה) בכל לבבך ובכל נפשך, אלא, אזהרה ליחיד אזהרה לצבור:
@100 **ונתתי מטר ארצכם.** עשיתם מה שעליכם, אף אני אעשה מה שעלי: **בעתו.** בלילות שלא יטריחו אתכם. דבר אחר בעתו, בלילי שבתות שהכל מצויין בבתיהם: **יורה.** היא רביעה הנופלת לאחר הזריעה שמרוה את הארץ ואת הזרעים: **ומלקוש.** רביעה היורדת סמוך לקציר למלאות התבואה בקשיה. ולשון מלקוש, דבר המאוחר. כדמתרגמינן (בראשית ל, מב) והיה העטופים ללבן, לקישיא. דבר אחר לכך נקראת מלקוש שיורדת על המלילות ועל הקשין: **ואספת דגנך.** אתה תאספנו אל הבית ולא אויביך. כענין שנאמר (ישעי' סב, ח. ט) אם אתן את דגנך וגו' כי מאספיו יאכלהו, ולא כענין שנאמר (שופטים ו, ג) והיה אם זרע ישראל וגו' :
@101 **ונתתי עשב בשדך.** שלא תצטרך להוליכה למדבריות. דבר אחר שתהיה גוזז תבואתך כל ימות הגשמים ומשליך לפני בהמתך ואתה מונע ידך ממנה שלשים יום קודם לקציר ואינה פוחתת מדגנה: **ואכלת ושבעת.** הרי זו ברכה אחרת, שתהא ברכה מצויה בפת בתוך המעים:
@102 **השמרו לכם.** כיון שתהיו אוכלים ושבעים, השמרו לכם שלא תבעטו, שאין אדם מורד בהקדוש ברוך הוא אלא מתוך שביעה, שנאמר (דברים ח, יב. יד) פן תאכל ושבעת ובקרך וצאנך ירבין, מה הוא אומר אחריו, ורם לבבך ושכחת: **וסרתם.** לפרוש מן התורה ומתוך כך ועבדתם אלהים אחרים. שכיון שאדם פורש מן התורה הולך ומדבק בעבודה זרה. וכן דוד אמר (שמואל א' כו, יט) כי גרשוני היום מהסתפח בנחלת ה' לאמר לך עבד וגו' , ומי אמר לו כן, אלא כיון שאני מגרש מלעסוק בתורה, הריני קרוב לעבוד אלהים אחרים: **אלהים אחרים.** שהם אחרים לעובדיהם, צועק אליו ואינו עונהו, נמצא עשוי לו כנכרי:
@103 **את יבולה.** אף מה שאתה מוביל לה, כענין שנאמר (חגי א, ו) זרעתם הרבה והבא מעט: **ואבדתם מהרה.** על כל שאר היסורין אגלה אתכם מן האדמה, שגרמה לכם לחטוא. משל למלך ששלח בנו לבית המשתה והיה יושב ומפקידו [ומפקדו] אל תאכל יותר מצרכך שתבא נקי לביתך, ולא השגיח הבן ההוא. אכל ושתה יותר מצרכו והקיא וטנף את כל בני המסבה. נטלוהו בידיו וברגליו וזרקוהו אחורי פלטרין [פלטין] : **מהרה.** איני נותן לכם ארכא. ואם תאמרו והלא נתנה ארכא לדור המבול, שנאמר (בראשית ו, ג) והיו ימיו מאה ועשרים שנה, דור המבול לא היה להם ממי ללמוד ואתם יש לכם ממי ללמוד:
@104 **ושמתם את דברי.** אף לאחר שתגלו היו מצינים במצות, הניחו תפלין, עשו מזוזות כדי שלא יהיו לכם חדשים כשתחזרו. וכן הוא אומר (ירמיה לא, כ) הציבי לך צינים:
@105 **לדבר בם.** משעה שהבן יודע לדבר, למדהו תורה צוה לנו משה (דברים לג, ד) , שיהא זה למוד דבורו. מכאן אמרו, כשהתינוק מתחיל לדבר, אביו מסיח עמו בלשון הקדש ומלמדו תורה, ואם לא עשה כן הרי הוא כאלו קוברו, שנאמר ולמדתם אתם את בניכם לדבר בם וגו' למען ירבו ימיכם וימי בניכם:
@107 **למען ירבו ימיכם וימי בניכם.** אם עשיתם כן ירבו, ואם לאו לא ירבו, שדברי תורה נדרשין מכלל לאו הן, ומכלל הן לאו: **לתת להם.** לתת לכם אין כתיב כאן, אלא לתת להם, מכאן נמצינו למדים תחית המתים מן התורה:
@108 **שמר תשמרון.** אזהרת שמירות הרבה להזהר בתלמודו שלא ישתכח: **ללכת בכל דרכיו.** הוא רחום ואתה תהא רחום, הוא גומל חסדים ואתה גמול חסדים: **ולדבקה בו.** אפשר לומר כן, והלא אש אוכלה הוא, אלא הדבק בתלמידים ובחכמים ומעלה אני עליך כאלו נדבקת בו:
@109 **והוריש ה'.** עשיתם מה שעליכם אף אני אעשה מה שעלי: **ועצמים מכם.** אתם גבורים, והם גבורים מכם, שאם לא שישראל גבורים, מה השבח שמשבח את האמוריים לומר ועצמים מכם, אלא אתם גבורים משאר אמות והם גבורים מכם:
@111 **לא יתיצב איש** וגו' **.** אין לי אלא איש, אמה ומשפחה ואשה בכשפיה מנין, תלמוד לומר לא יתיצב מכל מקום. אם כן מה תלמוד לומר איש, אפלו כעוג מלך הבשן: **פחדכם ומוראכם.** והלא פחד הוא מורא, אלא פחדכם על הקרובים ומוראכם על הרחוקים. פחד לשון בעיתת פתאום. מורא לשון דאגה מימים רבים: **כאשר דבר לכם.** והיכן דבר (שמות כג, כז) את אימתי אשלח לפניך וגו' :

@1 **והיה עקב.** רוצה לומר בשכר שמיעתכם משפטי התורה וקיימם אותם ימתין לכם הש' יתעלה הברית והחסד אשר נשבע לאבותיכם כדי שיהיה שמו לכם אל העת היותר נאות כמו שקדם בסוף פרשת ואתחנן ואולם עתה יתן לכם ארץ שבעה עממים כמו שזכר אחר זה וכמו שקדם פעמי' רבות:
@2 **ואהבך והרבך וגו'.** ר"ל שבשכר זה יאהבך הש' ית' ותדבק השגחתו בך ויברכך. רוצה לומר שיצליחך וירבך כי ירבה זרעך וזה כי השם יתעלה יברך פרי בטנך ויישיר דבר ההוייה שלא יקרה בה הפסד:
@2 **וברך פרי אדמתך.** בדרך שיהיה לך רב דגן ותירוש ויצהר ויברך הפירו' והצאן בדרך שיפרה וירבה מקנך וזה יהיה על האדמה אשר נשבע לאבותיך לתת לך והנה ביאר בזה כי בשכר קיומו משפטי השם יתעלה יירש הארץ ויצליח בה ברבוי הבני' וברבוי הקנינים:
@3 **ברוך תהיה מכל העמים וגומ'.** הנה מיתרון השגחת השם יתעלה בך תהיה ברוך מכל העמים באופן שלא יהיה בך עקר ועקדה ולא בבהמתך וזה ענין נפלא מאד בעם גדול כזה:
@4 **והסי' יי' ממך כל חולי וכל מדוה מצרים הרעים.** אמנם אמר זה לפי שהיו ישראל חושבים בתחלת הענין שיהיה ממנהג השם יתעלה להמציא הרעות ולא הטובות כמו שזכרנו במה שקדם ולזה אמר שלא די שלא יביא השם יתעלה עליהם רעות אבל יסיר מהם כל חולי ולא יחשבו גם כן שיהיה דרך השם יתעלה לחדש בטובות ולא יוכל לחדש רעות כמו שהיו חושבים קצת הקודמים כי שם שני אלוהות הא' עושה הטובות והאחד עושה הרעות כי כבר יחדש רעות נפלאות כמו מכות מצרים בכל שונאי ישראל:
@5 **ואכלת את כל העמי' וגו'.** אמר שבשכר זה גם כן תשחית כל העמים אשר יי' אלהיך נותן לך:
@5 **ולא תחוס עינך עליהם.** הזהיר בזה שלא לרחם עליהם כדי שלא יחטיאו את ישראל:
@5 **ולא תעבוד את אלהיהם.** ביאר בזה שאם תרחם עליהם לבלתי השחיתם הנה יהיה זה סבה אל שתעבוד אל אלהיהם כי החמלה עליהם הוא מוקש לך עוד הזהירם שלא ייראו שלא יוכלו להוריש הגוים הרבים ההם כי יש להם לבטוח שיד השם יתעלה לא תקצר להוריש' בעבור מה שראו מנפלאותיו שעשה ביציאת מצרים:
@9 **וגם את הצרעה ישלח יי' אלהיך בם.** ידמה שהצרעה היה ממיתה אותם או ירצה בזה שהשם יתעלה ימציא להם מה שימיתם בדרך שלא יהיו הנשארים והנסתרים מפני בני ישראל כאמרו ויי' השליך עליהם אבנים גדולות מן השמים:
@11 **ונשל יי' את הגוים האלה.** אמר שמעט מעט ישליכם השם יתעלה מפני בני ישראל. כי לא יוכלו לכלותם מהר פן תרבה עליהם חית השדה. והנה אמר זה על צד המשל לגוים אשר סביבותיהם שהם חוץ מן הארץ הזאת אשר הוגבלת להיות לישראל כי בראותם זה יעזרום לפחדם שיעשו להם ישראל ככה כמו שעושים לאלו אך בלכדם עיר אחר עיר לא ירגישו בזה כל כך גם הגוים אשר צונו להשמידם ולא תהיה במלחמה עם עם רב מאד ואף על פי שיד השם יתע' לא תקצר הנה יבקש על הרוב במה שיעשוהו הסבות הנאותות כשיתכן זה כמו שזכרנו במקומות רבים במה שקדם לנו בזה הספר:
@13 **לא יתיצב איש בפניך עד השמידך אותם.** שלא יוכלו איש מהם להתיצב לפניך להלחם עמך ויתמיד להם השפלות והדלות הזה עד שכבר תשמיד אותם לגמרי:
@14 **פסילי אלהיהם שרפון.** רוצה לומר שלא תהנו ממנו כי מזה הצד זכר זה בזה המקום כמו שנתבאר במה שאמר אחר זה לא תחמוד כסף וזהב עליהם ולקחת לך והנה הזהיר בו מלהנות בצפוי הפסילים כל שכן בפסילים עצמם:
@14 **פן תנקש בו.** רוצה לומר פן יהיה לך למוקש ויביאך לעבוד עבודה זרה וזה כי לפעמי' יתכן במי שלקח זה שיצליחו נכסיו ויחשוב שמה שבא מן העבודה זרה בידו סבב זה ויביאהו זה לעבוד עבודה זרה:
@14 **כי תועבת יי' אלהיך הוא.** רוצה לומר שזה הדבר הוא נתעב ומרוחק אצל השם יתעל:
@15 **ולא תביא תועבה אל ביתיך וגומ'.** רוצה לומר לא תביא זה הדבר המרוחק בביתך כי זה יסבב שתהיה חרם כמוהו ותשמר:
@15 **שקץ תשקצנו ותעב תתעבנו כי חרם הוא.** בדרך שלא תקרבהו לך ליהנות בו בצד מהצדדים כי חרם הוא ולזה תחוייב להחרימו ולכלותו בדרך שלא ישאר לו שום מציאות:
@17 **למען ענותך לנסותך לדעת את אשר בלבבך.** הרצון זה שהשם יתעלה הסכים לעונת אותם זה הזמן הארוך אשר הוליכם במדבר והנה היתה תוחלתם בירושת הארץ תוחלת ממושכה כדי נסותם וליסרם בכל זה הזמן אם הם עדין חזקים בשמירת מצות השם יתעלה אם לא ולזה יסרם שם על מרותם פיו תכף שהיו עושין המרי כדי שיהיו חזקים בשמירת מצות השם יתעלה לטוב להם ולהורישם את הארץ אשר נשבע לאבות וכבר ענה אותם השם יתעלה שם באופן אחר מהענוי והוא שכבר הרעיבם וענה אותם במה שחסר להם שם מים בקצת המקומות ולא היה להם בשר לאכול ולא רקות ומיני קטנית ולא שומים ולא בצלים ושאר מה שידמה לזה גם לא היה להם לאכול זולתי אל המן עיניהם כדי להודיע להם עוצם נפלאות השם יתע' עד שכבר החיה עם רב כזה במדבר בזולת לחם במן שהוריד להם בדרך פלא והיה עוד מהפלא בזה שלא בלתה שמלתם מעליהם באותם ארבעים שנה ולא בלו מנעליהם מעל רגליהם והיה זה כולו להתמיד להם בזה הזמן הארוך ראיית אלו הנפלאות העצומות כדי שיורגלו בהאמנת השם יתעלה:
@20 **וידעת עם לבבך כי כאשר ייסר איש את בנו.** רוצה לומר כי כבר ידעת כי השם יתעלה ייסר אותך על מרותך פיו בהיותך במדבר כאשר ייסר איש את בנו וזה שהאיש שייסר את בנו תכף מרותו כדי שיכיר שמריו היה סבה שהכהו אביו ויקח בזה מוסר. ואולם השם יתעלה לא נסה לענוש הרשעים תכף מרותם כי הוא ארך אפים אך לאהבתו ישראל ייסרם במדבר תכף מרותם כדי שיכירו כי מרים היה סבה אל הרע שקרה להם ויקחו בבזה מוסר ויכנעו לעבודת ה' ית':
@23 **ארץ חטה ושעורה.** הנה שבח ארץ ישראל באילו המינים מהפירות והם חטה ושעורה שהם המינים היותר נבחרים שבמיני התבואה והקדי' החטה שהיא היותר נבחרת מהשעורה ושעורה היא כבדת מגפן יכי הוא מזון ואולם היין אינו הכרחי כל כך כי יוכלו לשתות מים והגפן יותר נכבד מהתאנה והתאנה יותר נכבד מהרמון וזה מבואר בנפשו:
@23 **ארץ זית שמן ודבש.** הנה כמו שהשמן מתואר לארץ ישראל מצד שהיא ארץ זיתים נכונים לעשות מהם שמן כן הדבש מתואר לארץ ישראל מצד שהיא נכונה להצמיח פירות נכונים יהיה מהם הדבש והם התמרים אך לא כוון בזה בדבש הדבורים כי הדבורים יחדשוהו לא הארץ לפי שהשמן הוא יותר הכרחי מהדבש הקדימו ואין ראוי לבאר מזה שיהיה הרמון יותר נכבד מהזיתים והתמרי' כי כבר התחילו לומר ארץ פעם אחרת ולא המשיך זה אל מה שאמר ארץ חטה ושעורה וזאת הסבה גם כן אין ראוי לבאר מזה שיהיה כל אחד מאלו המינים יותר נכבד מהלחם לפי שהזכירו באחרונה כי כבר אמר בו ארץ פעם שלישית ולא המשיכו אל המינים האחרים:
@24 **ארץ אשר לא במסכנות תאכל בה לחם.** ר"ל שלא תאכל הלחם בדרך עוני וחסרון כי הארץ נותנת פירות הרבה ולזה ימצא בה תמיד רבוי הלחם:
@24 **לא תחסר כל בה.** ר"ל כי כל הדברים ארש יצטרכו לאדם ימצאו שם:
@24 **ארץ אשר אבניה ברזל וגומ'.** לפי שהברזל והנחשת והוא הברזל הקשה מאד יצטרכו לאנשים מאד במלאכותיהם זכר שהם נמצאים בארץ ישראל הרבה:
@25 **ואכלת ושבעת וגו'.** ר"ל בעבור שהאכילה והשביעה לא יהיה לפי הנהוג כי אם מחלתם הנה הרצון בזה שמי שאכל לחם כדי שישבע חייב לברך השם יתעלה והראיה עוד כי מהלחם ידבר כי ממנו דבר קודם בסמוך ובו לבדו זכר אכילה באמרו תאכל בה לחם והנה זאת הברכה היא לשם יתעלה להודות לו על המזון שחנן אותנו כי אם תהיה הכונה בזה שנודה לו לבד על הארץ הטובה אשר נתן לנו כמו שאיפשר שיחשב זה מזה הפסוק הנה לא תהי' ההודאה שלמה כי מהארץ לא יצא לחם בזולת חנינת השם יתע' ולזה יתן הסדר שיהיה הברה לשם יתעלה תחלה על אשר נתן לנו זאת הלחם ואחר נודה על שנתן לנו הארץ הטובה שהיא מוכנת מאד לצאת ממנה לחם תמיד ולפי שלא תלה זאת המצוה בארץ למדנו מזה שהיא נוהגת בכל מקום עם שעצם הענין מחיי' זה כי בכל מקום שאנחנו בו השם יתעלה נותן לנו לחם אשר נאכל ואולם בעונותינו עתה שאין אנו מחזיקים בארץ ראוי שנתן לשם יתעלה תודה על שנתנה לאבותינו ולנו לפי מה שאנחנו מקוים ולזה ראוי שנבקש ממנו שישיבנו שם ולזה תקנו בזה אנשי כנסת הגדולה אלו שלש ברכות ולפי שאמ' על הארץ הטובה אשר נתן לך והנשים לא היו יורשות הארץ אלא על צד הזרות שקרה להם לבנות צלפחד הנה הענין בספק אם מפני שאינן בכלל נתינת הוראה על הארץ הטובה אשר נתן להם תפטרו מברכ' המזון או נאמ' כי מפני שישנן בכלל נתינ' הודא' על הלחם שחננו השם יתעלה יתחייבו בברכת המזון עם שהנשים גם כן שמחו בכללן באץ הטובה שאם לא ירשו הן בעצמן ירשו בעליהן או אביהן אשר בטובתן טוב להן:
@26 **השמר לך פן תשכח.** הוסיף להזהירם שלרוב השומן והלשוה לא ישכחו השם יתעלה ומצותיו לפי שכבר שער השם יתעלה שכן יהיה הענין בסוף והשתדל להצילם מזה כפי היכולת והנה ספר להם שאין ראוי שישכחו השם יתעלה שעשה להם כל הנפלאו' האלו והוא שכבר הוציאם ממצרים שהיו עבדים בזה האופן הנפלא שהתפרסם בתורה והוליכם במדבר הגדול והנורא שהיה משכן הנחשים השרפים הממיתים והיה מקום צמאון שאין בו מים והוציא להם הש' יתע' מים מהצור הקשה והצילם מהיזק הנחשים והעקרבים לולי העת שסבב מרים ונזקו בנחשים מהם על צד הטלת העונש עליהם:
@31 **המאכילך מן במדבר.** רוצה לומר שהיה מאכל שלא ידעוהו הקודמים כי השם יתעלה חדשו אז על דרך פלא:
@31 **למען ענותך.** בחסרון המאכלים הנהוגים כדי שתכיר נפלאות השם יתעלה להיות האנשים בכל מה שירצה וכדי שינסה אותך איך תתנהג במצותיו עם ראותך אלו הנפלאות כדי שכאשר יתבאר לו חיותך ראוי לירושת הארץ יתננה לך ולזה גם כן השם יתעלה מיסרם במדבר על מרים תכף בלי איחור כדי שישמרם בקלות אל שיהיו הזקי ההמשך למצוה השם יתעלה:
@32 **ואמרת בלבבך כחי ועצם ידי.** רוצה לומר אולי כאשר תשכח השם יתעלה שעה לך אלו הנפלאות תאמר בלבבך כי בכוחך ירשת הארץ ולזה צוה שיזכור השם יתע' כי מאתו ינתן הכח לישראל לנצח האומות ההם מצד שמרו בריתו עם האבות והודיעם עם זה שאם ישכחו השם יתע' ויעבדו אלהים אחרים יאבדו כאבוד הגוי אשר יי' מוריש מפניהם:
@36 **שמע ישראל אתה עובר היום את וגו'.** ביאר להם שהגוים שהם באים לרשת הם גדולים ועצומים מישראל ושם בני ענקי שלולי יד השם יתעלה לא יוכל איש להתיצב לפניהם עם שהם בערים גדולות בשמים לרוב גובה הבירות והמגדלים והמבצרים אשר שם ולזה צריך אתה לדעת שלא יהיה נצוחך אותך מצד עצמך אך השם יתעלה הוא המשמיד אותם מפניך:
@39 **אל תאמר בלבבך בהדוף יי' אלהיך וגו'.** ביאר לך כי לא בצדקתך ירשו הארץ אך ברשעת הגוים הם כי לולי רשעתם לא ענשם השם יתעלה בזה העונש כי מעשה ידיו כלם ולזה אמר לאברהם כי לא שלם עון האמורי עד הנה ולפי שלא תספיק זאת הסבה לבד בהורשת הארץ לישראל ביאר שזה הטוב היה לישראל מצד ברית השם יתעלה עם האבות לא בצדקת ישראל לבדה כי אל היתה עדין באופן שתספיק בכמו זאת ההשגחה הנפלאה והנה היה התועלת בזה אולי אם יחשבו ישראל כי צדקתם היתה סב בירושת הארץ עם רשעת הגוים ההם הנה בראותם כי כל הגוים עובדי ע"ז לא ייראו אם יעשו כמעשיהם שיורשו מן הארץ כי אינם צדיקים מהם בדדרך שיתן להם הש' יתע' הארץ בצדקתם אך עתה שידעו כי רשעת הגוים היתה הסבה בזה ולא היתה הארץ לישראל כי אם מצד ההשגחה הפרטית אשר היה דבוקה באבות יש לירוא שברשעתם תאבד הארץ מהם ע"י שאר הגוים כשתהיה להם מצד ההשגחה הכללית:
@41 **וידעת כי לא בצדקתך וגו'.** ביאר להם כי לא בצדקתם יתן להם השם יתעלה הארץ לפי שהם עם קשה ההעתק מהפחיתיו' אשר גדלו עליהם במצרים ויורה זה כי מעת צאתם ממצרים עד בואם לערבות מואב היו תמיד ממרים עם השם יתעלה וזה כי בהיות משה בהר חורב לקבל התורה סרו ישראל מהר מאמונת השם יתעלה עם מה ששמעו באזניהם עשרת הדברים מהש' יתעל באמצעות הקול הנפלא ועשו להם עגל מסכה.
@44 והנה ספר אז לישראל היותו יושב אז בהר מ' יום ומ' לילה בזולת אכילה ושתיה והלוחות שנתן לו השם יתע' היו כתובים באצבע אלהים והיו בהם עשרת הדברים ששמעו כם בזה האופן הנפלא במעמד הר סיני לפרסם לכל ישראל אלו הנפלאות וספר שכבר רצה השם יתעלה להשמידם אז לולי תפלת משה והוא ירד מן ההר וראה חטא ישראל הנפלא והיה זה סבה אל ששבר הלוחות מרוב כעסו כאלו הורה בזה כי לשואת נתן תורה לישראל כי תכף עברו על היותר קשה מנה והוא דבור לא יהיה לך:
@53 **ואתנפל לפני השם בראשונה מ' יום וגו'.** ירצה לפי מה שאחשו' כי הראשונ' בסוף המ' יום כשרא' משה כעס השם יתע' על יש' התנפל לפניו ובקש ממנו שלא יכלה עמו באפו ואחר ירד תכף לנקו' העון כפי מה שאפשר כי לא יתכן שיתפלל לשם יתעלה בעדם והם עדין מחזיקים ברשעתם ולזה ירד תכף מההר ושבר הלוחות בראותו מעשה העגל וצוה להרוג כי העובדים ולשרוף העגל להאבידו ואחר זה היה יותר נכון שיבקש מה' ית' שישוב חרון אפו מישראל אחר שביער הרע מקרבם. והתנפל לפי השם יתעלה בראשונה. שהתנפל לפניו שלא יכלם תכף כמו שזר עליהם ועמד בזה ההתנפלות השני מ' יום ומ' ילה בזולת אכילה ושתיה עד שנעתר לו השם יתעלה וכבר ביארנו על דבר קרח כי יתכן שיענש בחטא אחד כל העם מצד היותם מתאחרים ולזה לא הספיק למשה בערו הרע מקרב ישראל להשיב חרון אפו מהם והוא אפשר שנאמר כי זה בראשונה שב אל אמרו מ' יום ומ' ליה לחם לא אכלתי ומים לא שתישי ויהיה הרצון בזה וכבר התנפלתי לפי יי' וכמו שעמדתי בראשונה מלאכול ולשתות מ' יום ומ' לילה כן עמדתי אז מלאכול ולשתות מ' יום ומ' לילה:
@55 **ובאהרן התאנף יי' וגו'.** הנה אף השם יתעלה היה על אהרן על שכבר היה סבה באופן מה לחטא ישראל ואף על פי שהיתה כונתו טובה כמו שביארנו בפרש' כי תשא והעד שהיתה כונתו טובה שכבר נמחל לו ונתנה הכהונה לו לזרעו וזה לא היה ראוי אם היה חושב להעשות כומר לע"ז אך היה ראוי שיהיה ענשו יותר חזק מהאנשים שהשתחוו לעגל שלפי יתרון מעלת החוטא ראוי שיהיה העונש יותר גדול ועוד כי משה זכר בזה המקום שהתפלל על ישראל אחר הריגתו לחוטאים ולזה הוא מבואר כי הוא התפלל על אשר לא חטאו בזה מצד עצמם ואמר אחר זה ואתפלל גם בעד אהרן וזה ראיה שלא חטא אהרן בזה כי אם במקרה אך הצילם מהחטא לפי כוחו ומפני מה שנמשך במקרה מהחטא לישראל בסבתו הוצרך אל שיתפלל משה עליו להצילו מההשמד וכבר הרחבנו המאמר בזה בפרשת כי תשא.
@59 והנה להשים הספור לבאר להם שהם היו תמיד ממרים עם הש' יתע' זכר להם ענין מה שהקציפו השם יתעלה בתבערה ובמסה ובדבר המרגלים קודם שיבאר הענין מהתפלה שהתפלל לשם יתעלה בהר להשיב חרון אפו על כל החטא שהיה בעשיית העגל כבר ביארנו ענין התפלה הזאת הפרש' כי תשא וממה שבארנו שם התבאר הכונה במה שנזכר התפלה בזה המקום כי הכונה אחת ואם הומר הלשון והסדור בדברים:
@65 **בעת ההיא אמר ה' אלי פסל לך שני לוחות אבנים וגו'.** כבר התבאר בפרשת כי תשא כי אז עמד גם כן בהר מ' יום ומ' ליה בכל פעם בזולת אכילה ושתייה. רוצה לומר כשנתנו לו הלוחות השניות ולא התבאר בזה המקום ששלש פעמי' עמד שם משה בהר ארבעים יום וארבעים לילה בכל פעם בזולת אכילה ושתיה והרצון נאמרו לחם לא אכלתי שלא אכל מזון שאם היה הרצון בו לחם ממש לא היה זה פלא כי גם ישראל היו בלתי אוכלים לחם אך היו אוכלים המן ולזה יחוייב שיהיה הרצון באמרו לחם לא אכלתי שלא אכל שום מזון וזה ממה שאין ספק באמתתו עם שכבר מצאנו באליהו שעמד מ' יום מלאכול:
@70 **ובני ישראל נסעו מבארות בני יעקן מוסרה.** רוצה לומר. מבארות בני יעקן וממוסרה כמו שנזכר בפרשת מסעי שנאמר ויסעו ממוסרה ויחנו בבני יעקן שם מת אהרן ידוע שלא מת אהרן במוסרה ולא בבני יעקן ואולם מת בהר ההר ונקבר שם וזה היה אחר מסעו' רבות מעת היותם בבני יעקן כמו שנזכר בפרשת מסעי ולזה היה הרצון בזה כי שם באלו המסעות שנמשכו זה לזה מת אהרן ונקבר שם על דבר מי מריבה וכאלו היה זה הספור לספר מרי ישראל ולזה הזכיר בארות בני יעקן כאלו באר כזה כי בכל המקומות שעברו אז עד היותם בקדש היה להם מים לשתות ולזה נתרעמו ישראל על מי מריבה בזולת סבה גדולה תביאם אל זה ולזה כפר כי משם נסעו הגדגוד' יטבתה כמו שנזכר בפרשת מסעי והנה זכר ביטבתה שהוא ארץ נחלי מים להעיר עוד כי בסבת מי מריבה מת אהרן כמו שנזכר בפרשת פרה ולהעיר שבכל המקומות שבאו באלו המסעות היה להם מים עד בואם בקדש כמו שקדם:
@72 **בעת ההיא הבדיל ה' את שבט לוי.** רוצה לומר בעת מתן תורה לשאת ארון ברית ה' לא זכ' נשיאת שאר הכים לפי שזה לא יהיה אחר בא ישראל אל המנוחה ואל הנחלה אך נישאת הארון יהיה במלחמה אחר בא ישראל אל המנוחה ולא הנחלה כמו שנתבאר מהמלחמה שהיה בימי עלי:
@72 **לעמוד לפני יי' לשרתו.** מגיד ששרו' הלוי' הוא מעומד:
@72 **ולברך בשמו.** הנה מזה התבאר הכונה באמרו ושרת בשם ה' אלהיו וזה כי השרות הוא להודות לשם יתעלה ולברכו בפה בעת עשיית הקרבנות אך הכהנים היו מריעים בחצוצרות והלוים היו משוררים בפה וזה נתבאר ביאור קצת מזה המקום והנה נשלם הביאור בזה בספר עזרא:
@74 **ואני עמדתי בהר מ' יום כימים הראשונים וגו'.** הרצון בזה כי העלותו בהר על דבר הלוחות השניות עמד שם מ' יום ומ' לילה ואז התחנה לשם יתעל שילך בקרב ישראל ותדבק השגחתו בהם כמו שנזכר בפרשת כי תשא כי כבר אמר השם יתעלה על דבר העגל שילך מלאכו לפניהם אך השגחתו יתע' לא תדבק בהם וזה באמת היה דבר רע לישראל מאד ולזה השתדל מש בעת ההיא אל שירצה השם יתעלה ללכת בקרב' כי בזה יתכן להם שיירשו את הארץ ואף על פי שלא הגיע העת עדין וכאשר נעתר לו השם יתעלה על זה אמר לו שילך למסע לפניהם ויבאו ויירשו את הארץ כי לא היו צריכים להמתין הקץ אחר שהשגחת השם יתע' הדבק בהם והנה אז ערבב הענין מרי ישראל על דבר המרגלים ונתאחרו מפני זה במדבר מ' שנה כמו שקדם והנה זכר בזה המקום להזכיר לישראל כי הם היו ממרים עם השם יתעלה תמיד כמו שקדם:
@76 **ועתה ישראל מה ה' אלהיך וגו'.** רוצה לומר שהוא אינו מעמיס עליך דבר שיהיה ראוי שיכבד עליך כי מה שישאל מעמך לקיים מצותיו אינו כי אם לטוב לך ולעבוד את ה' אלהיך וגו' הכונה בו ענין התפלה כמו שביארנו באמרו ואותו תעבדו:
@76 **ועבדת את ה' אלהיך בכל לבבך ובכל נפשך.** בטעם אמרו ומצאת כי תדרשנו בכל לבבך ובכל נפשך והרצון בו שתהיה תפלתך לו בכוונה שלמה יתאחדו כחתיך המתעוררים והם הנכללים נאמרו בכל לבבך וכחותיך המשיגים והמציירים שהם הדמיון והשכל והנלוים אליהם והם הנכללים באמרו ובכל נפשך:
@80 **ומלתם את ערלת לבבכם.** רוצה לומר שתסירו אוטם לבבכם באופן שתשמעו אל מצות השם יתעלה בכללם. ולא תקשו עוד ערפכם. שלסור מהתכונות הרעות שנשקעתם בהם כי הרבה מרים עד עתה ודעו כי השם יתעלה שהוא מנהיג אתכם הוא אלוה המנהיגים הנבדלים כי הם עלולים ממנו ומהשפע שיושפע ממנו יעשו מה שיעשו והוא המושל על כל מי שיש לו שום ממשלה והוא עושה גדולות וגבורות ונוראות ולזה יעניש אתכ' אם תחטיאו ואף על פי שלא יסודר לכם אז רע מצד ההשגחה הכוללת ולא תוכלו להמלט ממנו שלא יגיע לכם ענשו כי הוא בלתי נושא פנים לגדולים כי לפניו יהיה הגדול כקטון בהשפטו ולא יקבל שוחד שתבטח לפייסו בו כי הוא בלי צריך לדבר מנבראיו ולזה לא יצ' מלפניו רק יושר ומפני זה הוא עושה משפט השפלים החלושים כשיהיו עשוקים והם היתום והאלמנה:
@82 **ואוהב גר לתת לו לחם ושמלה.** ר"ל שהוא משגיח על הנרדפים כמו הענין בגר שאין לו עוזר מפני שאין לו קרובים והנה השם יתעלה ישגיח בו לתת לו לחם לאכול ובגד ללבוש וזה אמנם סודר ממנו יתעלה בו לפי מה שאחשוב מצד ההשגחה הכוללת שבה נותן לחם לכל בשר ואף על פי שאינו באופן שיתכן שתדבק בו ההשגחה הפרטי':
@83 **ואהבתם את הגר.** צוה לאהוב את הגר כי אין בשער עזרתו ולזה צוה עליו במקומות רבים מהתורה:
@84 **את ה' אלהיך תירא.** כבר פרשנו אלו המצות הנכללות בזה הפסוק בפרשת ואתחנן מלבד אמרו ובו תדבק והנה הרצון בו שישתדל שידבק בו כפי כחו וזה יהיה כשילמד התורה והחכמה אשר יתישר מהם להשגתו יתעלה לפי מה שאפשר וזהו הדבקות ולפי שזה לא יתכן לאדם אם לא באמצעות החכמים שילמדוהו זה כמו שביארנו בביאורנו לשיר השירים הנה כללה זאת המצוה שידבק בחכמים כי הם המישירי' אותו לקיים זאת המצוה והם יעמידו איש ואיש על מה שאפשר לו מזה:
@85 **הוא תהלתך.** רוצה לומר אין ראוי שתהלל זולתו כי הוא עשה אתך כל הנפלאות עצומות אשר ראו עיניך במצרים ועל הים ובמדבר בשבעים נפש ירדו אבותיך הנה זה אחד מהפלאים העצומים כי בארץ מצרים שדמו לכלות אתכם וענו אתכם תכלית הענוי כדי למעט אתכם השגיח ה' יתע' בכם באופן ששם שתכם בזה הרבוי הנפלא בזמן לא ארוך מאד כי לא עמדו שם כי אם מאתים ועשר שנה כמו שביארנו בספר ואלה שמות:
@87 **ואהבת את השם אלהיך וגו'.** למדנו מזה שהתורה הזאת היא נצחית כאמרו כבר שנשמור את משמרתו וחקתיו ומשפטיו כל הימים:
@88 **וידעתם היום כי לא את בניכם.** רוצה לומר אתם יודעים כל זה כי אין דברי את בניכם שלא ידעו ולא ראו כל אלו הנפלאות שזכר תכף כי עיניכם הרואות את כל מעשה השם הגדול אשר עשה:
@94 **ושמרתם את המצוה.** ר"ל הנה לזאת הסבה ראוי שתשתדלו בשמירת כל מצות השם יתע' כדי שתירשו את הארץ ותאריכו ימים עליה כמו שייעד להם השם יתעלה כי אתם ראיתם שקיים כל מה שהבטיח ועשה אלו הנפלאות העצומות אשר ייעד חדושם קדש התחדשם:
@96 **לא כארץ מצרים היא וגו'.** ידוע שאין מטר יורד במצרים ולזה יצטרכו להשקו' הארץ הנעבדת והנזרע ברגליהם:
@96 **כגן הירק.** להוליך מן מי היאור אל התעלו' אשר בהן ישקו השדה ההוא בל ארץ ישראל אינו כן כי למטר השמים תשתה מים ואם תחשבו שהמטר ירד שם וימעטו מפני זה פרות הארץ היא הנה תדעו כי ליושר ירידת המטר שם ידמה שהשגחת השם יתעלה תהיה תמיד בה מראשית השנה ועד אחרית השנה לתת בכל עת מה שיאות לצמחים כאלו תאמר שינשב שם הרוח בעת הצורך אל הרוחות וירד שם מטר בעת הצורך אל המטר:
@99 **והיה אם שמוע תשמעו וגו' לאהבה את ה' אלהיכם.** הנה ביארנו זאת המצוה בפרשת שמע:
@99 **ולעבדו בכל לבבכם ובכל נפשכם.** רוצה לומר להתפלל לפניו בכוונה שלמה כמו שביארנו בזאת הפרשה והנה הקדים לזכירת זאת המצוה אהבת השם יתעלה כי היא תסבב השגת השם יתעלה כפי מה שאפשר ובזה תהיה התפלה נשמעת ואחר ביאר שאם יעשו זה ימשך להם מהשגה הפרטית שיתן להם השם יתע' מטר ארצם בעתו בעת הזריעה והוא יורה ובעת נתינת התבואה פריה והוא מלקוש באופן שתתן הארץ דגן ותירוש ויצהר לא תמנע מזה בשנים מהשנים ויתן עשב בשדה שתאכל הבהמה הרועה שם ויאכלו וישבעו כי לא יחסר כל טוב:
@102 **השמרו לכם פן יפתה לבבכם.** ביאר להם שאם יעבדו ע"ז יהיה כל זה בהפך כי השמים לא יתנו מטר והארץ לא יתתן את יבולה ולזה יחסר להם המזון ויאבדו מהרה לסבות אחרות זכרם במה שקדם ובמה שיבא כו שחרב והדבר ומה שידמה להם:
@104 **ושמתם את דברי אלה על לבבכם.** רוצה לומר שתתבוננו להם תמיד כדי שתקחו מוסר ותשמרו מצות השם יתעלה ולא תפנו לע"ז והנה סמך עליה ענין תפלין של יד להישירנו אל שהכוונה בזה היא שיהיו נגד הלב כמו שביארנו בפרשת ואתחנן:
@104 **וקשרתם אותם לאות על ידכם. והיו לטוטפות בין עיניכם. ולמדתם אותם את בניכם.** כל זה ביארנו בפרש' ואתחנן ואולם אמר ושננתם לבניך וכאן אמר ולמדתם אותם את בניכם כי לעומק הדברים הכוללים פרשת שמע ולהיות מהשרשים היותר עקריים יצטרך המלמד לשנות הלמוד פעמים רבות מה שאין כן בזאת הפרשה כי איננה רבת העומק:
@105 **לדבר בם בשבתך בביתך וגו'.** הנה כבר ביארנו דבר זאת המצוה בפרשת ואתחנן וכאלו ביאר בכאן שצריך לחנך הקטנים בקריאה שמע ובפרשת והיה אם שמוע בעת השכיבה ובעת הקימה:
@106 **וכתבתם על מזוזות ביתיך ובשעריך.** כבר בארנו זאת המצוה בפרשת ואתחנן ובכאן התבאר שבמזוזות נכתבו פר' שמע ופר' והיה אם שמוע ובשכבו ובקומו חייב אדם לקרות שי אלו הפרשיות אך בתפלין של ראש ושל יד יהיו עם אלו השתי פרשיות אחרות והם קדש לי כל בכור והיה כי יביאך:
@107 **למען ירבו ימיכם וגו'.** בעבור שייעד בקיום התורה טוב נצחי לכל אחד מהדורות דור אחר דור:
@107 **כימי השמים על הארץ.** לדמנו מזה שהתורה היא נצחית גם כן כימי השמים על הארץ וזה ממה שלא נצטרך אל ביאור:
@108 **כי אם שמור תשמרון את המצוה הזאת וגו'.** ללכת בכל דרכיו. רוצה לומר להדמות אל מנהגי השם יתעלה ופעלותיו כפי היכולת כי הוא צדיק וישר ומשפיע מטובו לכל הנמצאות ומזה יקנה האדם מנהג להתנהג ביושר ואמת ולהטיב לזולתו כפי מה שאפשר לו הנה זה באור מה שצריך לזאת הפרשה:

@1 והיה עקב תשמעון וגו' עד סוף הפרשה.
@1 ואולם התועלות המגיעות ממנה הם כ"ו:
@1 **התועלת** הראשון הוא להודיע כי בשכר שמירת ישראל המצות המתין להם השם יתעלה השלמת קיום מה שנשבע לאבות אל העת היותר נאות להם כמו שביארנו בפרשת ואתחנן וזה כי ישמרם שלא יכלם בעוברם על מצות השם יתעלה כדי שלא תופר בריתו עם האמת ולזה אמר והיה עקב תשמעון את המשפטים וגומ'. ושמר ה' אלהיך לך את הברית ואת החסד אשר נשבע לאבותיך:
@1 **התועלת** השני הוא להודיע שכבר ימשכו משמירת מצות התורה וחקיה ומשפטיה טובות גופיות נפלאות לא טובות נפשיות לבד וימשכו מפני הפך זה רעות גופיות עצומות לא רעות נפשיות לבד וזה נכפל מאד בזאת הפרשה ובכל זה הספר ולזה אמר ואהבך וברכך והרבך וברך פרי בטנך וגו'. והיה אם שכוח תשכח את ה' אלהיך וגומ'. והיה אם שמוע תשמעון:
@1 **התועלת** השלישי הוא להודיע שמי שהבטיחהו השם יתעלה בנצוח איש מה על צד ההשגחה הפרטית ראוי שלא יירא שלא ינוצח מצד גבורת שכנגדו כי יד השם יתעלה לא תקצר ולזה זכר משה לישראל הנפלאות שעשה השם יתעלה לישראל אשר ראוי להם מצדם שלא ייראו מהגוים ההם אשר הם באים להלחם עמהם ואם הם יותר חזקים מעם ישראל כי יד השם יתעלה לא תקצר להפיל אותם לפניהם:
@1 **התועלת** הרביעי הוא להודיע כי אף על פי שהשם יתעלה שליט לעשו' כל מה שירצה וכל אשר יחפוץ הנה יבקש הסבות היותר נאותות שאפשר ולא יחדש מופת אלא אם יביא הצורך אל זה כי הוא אינו שונא הטבע כי הוא סדר אותו ולזה לא יחלוק עליו אלא בעת הצורך וביותר מעט שאפשר לו אז לחלוק עליו ולזה אמר ונשל ה' את הגוים האלה מפניך מעט מעט לא תוכל כלותם מהר פן תרבה עליך חית השדה ואף על פי שהיה השם יתעלה יכול לכלותם מהר ולשמור ישראל שלא תרבה עליהם חית השדה הנה לא הסכים לעשותו וזה אחר שאפשר הגעת המכוון לישראל בזולת זה:
@1 **התועלת** החמישי הוא במצת והוא מה שהזהירנו מלהנות בצפוי ע"ז וכ"ש בע"ז עצמה שנאמר לא תחמוד כסף וזהב עליהם ולקחת לך והנה התועלת בזאת האזהרה מבואר ממה שזכרנו לבאור זה הפסוק:
@1 **התועלת** הששי הוא במצו' והוא מה שהזהירנו מהביא תועבה אל ביתנו והוא ממון אנשי עיר הנדחת אעפ"י שלא היה צפוי עבודה זרה ולא עבודה זרה כי הוא חרם כמו שנזכר בפרשת עיר הנדחת וצותה התורה לשרפו אל תוך רחובה לפי שהוא חרם ובזה המקום הזהיר שלא להביא תועבה אל ביתנו ולפי שממון עיר הנדחת הוא חרם כמו שנזכר בפרשה היא למדנו מזה שאנחנו מוזהרים שלא להנות בו:
@1 **התועלת** השביעי הוא להודיע עומק מחשבות השם יתעלה שעם היות ישראל מתאחרים במדבר ארבעים שנה על צד העונש השתמש בזה לתועלת הוא לנסותם אם ישמרו מות השם יתעלה אם לא כדי לעמוד על העת שיהיו ראויי' בו לירושת הארץ ולזאת הסבה גם כן יסרם שם תכף מרותם מה שאינו ממנהג השם יתעלה כי הוא ארך אפים אבל להשגחת כל ישראל עשה זה כדי שישמרו מחטוא לה' ולזה גם כן ענם והרעיבם במדבר ארבעים שנה להראות לישראל נפלאות השם יתעלה כדי שיחזקו לשמור מצותיו:
@1 **התועלת** השמיני הוא להודיע שהפירות המיוחסים אל ארץ ישראל הם שבעה מינים לבד והם חטה ושעורה וגפן ותאנה ורמון וזתים ותמרים ומזה יתבאר אי זה מהמינים יוחסו לארץ ישראל:
@1 **התועלת** התשיעי הוא במצות והוא מה שצונו לברך השם יתע' אחר אכלנו לחם לשבוע ולתת לו תודה על הארץ הטוב' אשר נתן לנו אשר ממנה יצא לחם לט מעט ועל המזון שחנן אותנו ולפי שזאת ההנאה היא יותר שלמה מהנאת שביעת אכיל הפירות המיוחסים לארץ ישראל הנה נלמוד מזה שיהיה הדין באכילת הפירות ההם אך חכמים תקנו להם ברכה מעין שלש ברכות להמשך לכוונת התורה כי בזה תועלת להישיר אל האמונה שכל הטובות הם שפועות ממנו יתע' ומזה גם כן נתישרו לתקן שעל כל הנאה שתגיע לנו באכילת דבר או בשתייתו או בריחו נודה ונברך השם יתעלה הממציא לנו כל אלו הטובות:
@1 **התועלת** העשירי הוא להודיע שהוא מחויב שייחס האדם כל הטובות המגיעות אליו אל השם יתעלה כי מאותו הכל וכל שכן בדברים אשר לו יתכן הגעתם אם לא מצד העזר האלהי כמו הענין בנצוח ישראל אלו הגוים הגדולים והעצומים מהם שהיו בהם מבני הענק והיו בערים גדולות ובצורות בשמים ולזה אמר שאין ראוי שיאמר ישראל כחי ועוצם ידי עשה לי את החיל הה אך יזכור כי יי' אלהיו הוא הנותן לו כח לעשות חיל וידע כי הוא אשר ישמידם ויאבדם לא עוצם ישראל וכחו:
@1 **התועלת** האחת עשרה הוא מה שהודיע לישראל כי לא בצדקתם ישרשו ארץ אך ברשעת הגוים ההם מצורף עם ברית שם יתעלה תמיד עם האבות ונתן להם ראייה כי לא בצדקתם היה זה לפי שכבר היו ממרים עם השם יתעלה תמיד כמו שספר להם והיה ראוי שיעזבם השם יתעלה ולא ישתדל בהשלמתם לולי ברית השם יתעלה עם האבות ולזה הוא מבואר שלא היה זה הטוב לישראל כי אם בסבת האבות כי לא היו ראויים בהתחלה אל שישגיח השם יתעלה בהשלמתם בזה האופן הנפלא אך עכ"פ תצטרך לירושת הארץ בזה האופן צדקת ישראל כמו שזכר במקומות רבים שאם ישמרו מצות התור יבואו וירשו את הארץ ולזאת הסבה גם כן זכר שנתאחרו במדבר בסבת מרים. והנה התועלת בזה כדי לזרז ישראל שישמרו מצות השם יתעלה כמו שביארנו אצל ביאורינו אלו הדברים בזאת הפרשה:
@1 **התועלת** השתים עשרה הוא להודיע עוצם השתדלות משה להציל ישראל מהרע הנפלא שיעד לו השם יתעלה על דבר העגל עד שכבר התנפל לפני השם ית' ארבעים ים וארבעים לילה בזולת אכילה ושתייה עד שנעתר לו השם יתעלה ומחל להם כל חטאתם אשר חטאו בדבר העגל והנה הוצרך להתנפל לפני השם יתעלה כל זה הזמן הארוך לפי מה שאחשוב כי אולי בעבור כעם משה על הפלגת מרים ישראל בזה הוסר המעט מהדבקות שהיה לו עם השם יתעלה ולזה הוצרך להתמיד כל זה הזמן להשים עצמו באופן מהדבקות שהיה עם השם יתעלה עד שמפני צערו על אבדן ישר' ימלט העם בהשגיח השם יתעלה על משה להצילו מזה הצער הנפלא שהיה מצטער עליהם עם שרוב שקדו על זאת התפילה ועמדו מלאכול ולשתות הרבה צערו והיה זה סבה להשמע תפלתו:
@1 **התועלת** השלש עשרה הוא להודיע שצריך שמי שישתדל בהסרת הרע מה שישתדל בזה בהדרגה קצת אחר קצת כי אולי אם יכוין להסירו לגמרי תכף לא יוכל עליו ולזה צריך שיכוין להסיר ממנו תחלה מה שלא יכבד מאד להסירו ואחר זה יגרשהו מעט מעט בהדרגה ולזה תמצא שספר כי בראות משה אף השם יתע' וחמתו ורצותו לכלות ישראל בקש מהשם יתעלה להמתין הרע ההוא כדי שיוכל במה שהיה לו מהפנאי לנקות ישראל מהרע ההוא כי בזולת זה לא יהיה לומבא לבקש בעבורם מחילה ואח זה התנפל לפני השם יתע' זה הזמן הארך להסיר מישראל האף והחמה על כל חטאתם אך היה צריך עדין לשאול שיגיעו להם טובות מהשם יתעלה על צד ההשגחה הפרטית ואם לא הנה ישיגם הכיליון בכרח לפי הענין שהיו בו אז שהיו במדבר והוצרכו להלחם עם הגוים הוצרכו עזר מהשם יתעלה על צד ההשגחה הפרטית להיות להם ארץ ישבו בה וזהו מה ששאל משה ממנו יתעלה בארבעים יום השלישיים כמו שנתבאר בפרשת כי תשא ולזה סמך לזה הספור מה שצוה השם יתעלה למשה קום לך למסע לפני העם ויבאו ויירשו את הארץ להעיר שעד עתה לא היו נכונים לזה:
@1 **התועלת** הארבע עשרה הוא להודיע שראוי שיהיה האדם זריז שלא יסבב בשום צד להחטיא את הרבים ואף על פי שתהיה כוונתו הראשונה לשמרם מהחטא הלא תראה כי אהרן אף על פי שהיה משתדל בחכמתו להצל מן החטא כמו שבארנו בפר' כי תשא הנה מני שהיו דבריו באופן שנמשך מהם במקרה החטא לישראל כמעט שהשמידו השם יתעלה לולי תלת משה:
@1 **התועלת** החמש עשרה הוא מה שהודיע לנו בזה הספור כי בכל מקום שם או מעת נסעם ממוסרה עד קדש היה שם מים ולזה אמר מבארות בני יעקן ארץ נחלי מים כדי להודיע רוע תכונת ישראל שנתרעמו עמו תכף שהיו במקום שלא היה שם מים:
@1 **התועלת** השש עשרה הוא להודיע שאין ראוי למוכיח שיספר דבר יהיה אפשרי להית סבה אל שלא תקובל תוכחתו ולזה לא רצה משה לבאר בזה המקו' שיהיה מוכיח בו ישראל שעל דבר מי מריבה מת אהרן ונגזר מות על משה בעצמו כי החטא ההוא היה נעלם ויוכלו לומר כי לא יועיל ההשמר מהחטא כי אלו מתו בלא חטא עם גודל מעלתם ולזאת הסבה לא רצה לספר דבר קרח מפני שהיה גדול המעלה אצלם כדי שלא יהיה מקום לנטות מתוכחתו:
@1 **התועלת** השבע עשרה הוא להודיע שאין ענין התורה להעמיס עלינו דברי' זרים בלתי נאותים אך תצוה לבד על דברים מועילים מצד עצמותם בהפך הענין בשאר התורות לה אמר מה יי' אלהיך שואל מעמך כי אם ליראה וגומ' אשר אנכי מצוך היום לטוב לך:
@1 **התועלת** השמנה עשרה הוא להודיע כי כל דרכי השם יתעלה משפט לא ישא פנים ולא יקח שחד אך כקטון כגדול בהשפטם ולזה ראוי שייראו ממנו וימלו את ערלת לבבם ולא יקשו עוד ערפם כי הוא שליט להגיע להם עונש או גמול מצד השגחתו הפרטית כי הוא מושל על כל שאר הנבדלים אשר יסודר מהם פעולות מה באלו הנמצאות לפי מה שהכין להם השם יתעלה מהכח ביום הבראם ומה שיושפע ממנו לה תמיד ולזה יוכל השם יתעלה לשנות הסדורים ההם כי הוא מושל על כל מי שתהיה לו איזה ממשלה שתהיה והוא לבדו לעשות גדולות וגבורות ונוראות והם הפעולות המסודרות מהשגחה הפרטית לחלוק על המסודר מההשגחה הכוללת:
@1 **התועלת** התשע עשרה הוא להודיע שהשם יתעלה סדר המציאות באופן שאין החלושי' והשפלי' נתונים ביד מי שתקיף מהם כי גבוה מעל גבוה שומר וגבוהים עליהם ובזאת ההשגחה ינצל עני מחזק ממנו כמו שביארנו בביאורנו לספר איוב ובהיות הענין כן הנה מי שירדוף החלושי' ילך כנגד כוונת השם יתע' אשר השגיח בהם בזה האופן וישיגהו עונש נפלא מהשם יתעלה ולזה אמר ששם יתעלה עושה משפט יתום ואלמנה לזרז ישראל שישפטום בצדק כי בסוף כשלו בזאת המדה הפחותה כאמרו יתום לא ישפוטו וריב אלמנה לא יבא אליהם:
@1 **התועלת** העשרים הוא להודיע שהשם יתעלה סדר המציאות באופן שינתן לכל גויה די מחסורה כאמרו נותן לחם לכל בשר ומשביע לכל חי רצון ומזאת ההשגחה ימשך שיתן השם יתע' לגר תושב העומד בארצנו לחם ושמלה ולזה צוה לאהוב את הגר וללכת בדרכי השם יתעלה שהשגיח בו בזה האפן ובזה נקנה לעצמנו מדה חשובה:
@1 **התועלת** האחת ועשרים הוא במצות והוא מה שצונו להדבק בשכינה לפי מה שאפשר וזה יהיה בהתדבקנו לחכמים כי הם יישירונו על מה שיתכן שנגיע אליו מזה:
@1 **התועלת** השנים ועשרים הוא להודיע עוצם הפלא שעשה השם יתעלה לישראל במצרים כי במתי מעט באו שם ובזמן לא ארך שעמדו שם שמם השם יעת' בז הרבוי הנפלא עם רב השתדלות המצרים להמעיט אותם כפי יכלתם:
@1 **התועלת** השלש ועשרים הוא להודיע שתורתנו היא נצחי' לא תשתנה לעולם ולזה אמר ושמרתם את משמרתו וחקותיו ומשפטיו ומצותיו כל הימים ולזה גם כן אמר בפרשת והיה אם שמוע למען ירבו ימיכם וגומ'. כימי השמים על הארץ כי זה יורה שאם תשמרו מצותיו אשר הוא מצוה אתכם היום כמו שזכר שזאת הפרשה ירבו ימי ההולכים בדרך זה תמיד כימי השמים על הארץ וזה לאות כי כל התורה תתקיים כימי השמים על הארץ וזה ממה שלא יצטרך אל ביאור למעיין בזה הספר:
@1 **התועלת** הארבע ועשרים הוא להודיע שאלו הנפלאו' שספר משה לכל ישראל שעשה להם השם יתעלה ספרם למי שראו זה בעיניהם וידעו שהענין הוא כן כמו שספר מהם וזה ממה שיוסיף אמות בזה הספור ולזה אמר וידעתם כי לא את בניכם אשר לא ידעו ואשר לא ראו וגומ'. כי עיניכם הרואות את כל מעשה יי' וגו':
@1 **התועלת** החמש ועשרים הוא להודיע טוב ארץ ישראל גם בתועלות הגופיות כי היא תשתה מים תמיד למטר השמים ויבא בה הצריך לנתינת הצמחים פרים מרוחות וממטר על הרוב כאלו עיני השם יתעלה בה מראשית השנה ועד אחרית השנה:
@1 **התועלת** השש ועשרים הוא במצות והוא מה שצונו מפרשת והיה אם שמוע שנלמד אותה לבנינו ושנקרא זאת הפרשה בשכבינו ובקומינו ושנכתב' בתפילין של ראש ובתפילין של יד ועל מזוזות בתינו והנה התועלת באלו המצות לפי מה שהשרישה התורה מענינם הוא מה שהתבאר בפרשת ואתחנן ובפרשת בא על פרעה:
